	ALTER TABLE dbo.DoanPhimHuongDan ADD CONSTRAINT CkDoanPhimHuongDanKhongRong CHECK (LEN(LTRIM(RTRIM(TRANSLATE(MaDoanPhim COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaCongThuc COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(TieuDe COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(DuongDan COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0);
	GO
	ALTER TABLE dbo.ThucDon ADD CONSTRAINT CkThucDonKhongRong CHECK (LEN(LTRIM(RTRIM(TRANSLATE(MaThucDon COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaNguoiDung COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(TenThucDon COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(LoaiThucDon COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(TrangThai COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0);
