	CREATE OR ALTER PROCEDURE dbo.SpTaoThucDon
		@MaThucDon NVARCHAR(20), @MaNguoiDung NVARCHAR(20), @TenThucDon NVARCHAR(150),
		@LoaiThucDon NVARCHAR(30), @NgayBatDau DATE, @NgayKetThuc DATE, @TrangThai NVARCHAR(30) = N'Đã lưu'
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaThucDon không được để trống.',1;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF @TenThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@TenThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@TenThucDon không được để trống.',1;
		IF @LoaiThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@LoaiThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@LoaiThucDon không được để trống.',1;
		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
		IF NOT EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung = @MaNguoiDung) THROW 50001, N'Người dùng không tồn tại.', 1;
		IF @NgayBatDau IS NULL OR @NgayKetThuc IS NULL OR @NgayKetThuc < @NgayBatDau THROW 50009, N'Khoảng ngày thực đơn không hợp lệ.', 1;
		IF @LoaiThucDon IS NULL OR @LoaiThucDon NOT IN (N'Ngày', N'Tuần', N'Tự chọn') THROW 50010, N'Loại thực đơn không hợp lệ.', 1;
		IF @TrangThai IS NULL OR @TrangThai NOT IN (N'Đang dùng', N'Đã lưu', N'Đã kết thúc') THROW 50011, N'Trạng thái thực đơn không hợp lệ.', 1;
		INSERT dbo.ThucDon (MaThucDon, MaNguoiDung, TenThucDon, LoaiThucDon, NgayBatDau, NgayKetThuc, TrangThai)
		VALUES (@MaThucDon, @MaNguoiDung, @TenThucDon, @LoaiThucDon, @NgayBatDau, @NgayKetThuc, @TrangThai);
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpXoaMonKhoiThucDon
	 @MaThucDon NVARCHAR(20),@MaChiTiet NVARCHAR(20),@MaNguoiDung NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaThucDon không được để trống.',1;
		IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaChiTiet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaChiTiet không được để trống.',1;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
	 EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon;
	 IF NOT EXISTS(SELECT 1 FROM dbo.ChiTietThucDon WITH(UPDLOCK,HOLDLOCK) WHERE MaChiTiet=@MaChiTiet AND MaThucDon=@MaThucDon)
	 THROW 50016,N'Không tìm thấy chi tiết trong thực đơn.',1;
	 DELETE dbo.TuyBienNguyenLieuThucDon WHERE MaChiTiet=@MaChiTiet;
	 DELETE dbo.ChiTietThucDon WHERE MaChiTiet=@MaChiTiet;
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLayThucDonNguoiDung @MaNguoiDung NVARCHAR(20), @TuNgay DATE = NULL, @DenNgay DATE = NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
		IF @TuNgay IS NOT NULL AND @DenNgay IS NOT NULL AND @TuNgay > @DenNgay THROW 50017, N'Khoảng ngày tra cứu không hợp lệ.', 1;
		SELECT td.MaThucDon, td.TenThucDon, td.LoaiThucDon, td.NgayBatDau, td.NgayKetThuc, td.TrangThai,
			   ct.MaChiTiet, ct.NgayDung, ct.BuaAn, ct.MaMonAn, m.TenMonAn, ct.SoKhauPhan
		FROM dbo.ThucDon td LEFT JOIN dbo.ChiTietThucDon ct ON ct.MaThucDon = td.MaThucDon
			AND (@TuNgay IS NULL OR ct.NgayDung >= @TuNgay) AND (@DenNgay IS NULL OR ct.NgayDung <= @DenNgay)
		LEFT JOIN dbo.MonAn m ON m.MaMonAn = ct.MaMonAn
		WHERE td.MaNguoiDung = @MaNguoiDung
		  AND (@TuNgay IS NULL OR td.NgayKetThuc >= @TuNgay)
		  AND (@DenNgay IS NULL OR td.NgayBatDau <= @DenNgay)
		ORDER BY td.NgayBatDau DESC, ct.NgayDung DESC,
				 CASE ct.BuaAn WHEN N'Bữa sáng' THEN 1 WHEN N'Bữa trưa' THEN 2 WHEN N'Bữa tối' THEN 3 ELSE 4 END;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpCapNhatHoSoNguoiDung
		@MaNguoiDung NVARCHAR(20), @HoTen NVARCHAR(100), @ThuDienTu NVARCHAR(150)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF @HoTen IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@HoTen,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@HoTen không được để trống.',1;
		IF @ThuDienTu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@ThuDienTu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@ThuDienTu không được để trống.',1;
		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
		IF @HoTen IS NULL OR LTRIM(RTRIM(@HoTen)) = N'' OR @ThuDienTu IS NULL OR LTRIM(RTRIM(@ThuDienTu)) = N''
			THROW 50018, N'Họ tên và thư điện tử không được để trống.', 1;
		UPDATE dbo.NguoiDung SET HoTen = LTRIM(RTRIM(@HoTen)), ThuDienTu = LOWER(LTRIM(RTRIM(@ThuDienTu))) WHERE MaNguoiDung = @MaNguoiDung;
		IF @@ROWCOUNT = 0 THROW 50001, N'Người dùng không tồn tại.', 1;
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpCapNhatMucTieuDinhDuong
		@MaMucTieu NVARCHAR(20), @MaNguoiDung NVARCHAR(20), @NangLuong DECIMAL(10,2), @ChatDam DECIMAL(10,2),
		@ChatBotDuong DECIMAL(10,2), @ChatBeo DECIMAL(10,2), @ChatXo DECIMAL(10,2), @Natri DECIMAL(10,2)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaMucTieu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMucTieu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMucTieu không được để trống.',1;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF EXISTS(SELECT 1 FROM dbo.MucTieuDinhDuong WITH(UPDLOCK,HOLDLOCK) WHERE MaMucTieu=@MaMucTieu AND (MaNguoiDung<>@MaNguoiDung)) THROW 51030,N'Mã bản ghi đã thuộc đối tượng khác.',1;
		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
		IF NOT EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung = @MaNguoiDung) THROW 50001, N'Người dùng không tồn tại.', 1;
		IF @NangLuong IS NULL OR @NangLuong <= 0 OR @ChatDam IS NULL OR @ChatDam < 0 OR @ChatBotDuong IS NULL OR @ChatBotDuong < 0
		   OR @ChatBeo IS NULL OR @ChatBeo < 0 OR @ChatXo IS NULL OR @ChatXo < 0 OR @Natri IS NULL OR @Natri < 0
		   THROW 50019, N'Mục tiêu dinh dưỡng không hợp lệ.', 1;

			IF EXISTS (SELECT 1 FROM dbo.MucTieuDinhDuong WITH (UPDLOCK, HOLDLOCK) WHERE MaNguoiDung = @MaNguoiDung)
				UPDATE dbo.MucTieuDinhDuong SET NangLuong = @NangLuong, ChatDam = @ChatDam, ChatBotDuong = @ChatBotDuong,
					ChatBeo = @ChatBeo, ChatXo = @ChatXo, natri = @Natri WHERE MaNguoiDung = @MaNguoiDung;
			ELSE
				INSERT dbo.MucTieuDinhDuong (MaMucTieu, MaNguoiDung, NangLuong, ChatDam, ChatBotDuong, ChatBeo, ChatXo, natri)
				VALUES (@MaMucTieu, @MaNguoiDung, @NangLuong, @ChatDam, @ChatBotDuong, @ChatBeo, @ChatXo, @Natri);

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpCapNhatNganSach
		@MaNganSach NVARCHAR(20), @MaNguoiDung NVARCHAR(20), @MucNganSach DECIMAL(14,2),
		@LoaiNganSach NVARCHAR(20), @NgayBatDau DATE, @NgayKetThuc DATE
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaNganSach IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNganSach,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNganSach không được để trống.',1;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF @LoaiNganSach IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@LoaiNganSach,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@LoaiNganSach không được để trống.',1;
		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
		IF NOT EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung = @MaNguoiDung) THROW 50001, N'Người dùng không tồn tại.', 1;
		IF @MucNganSach IS NULL OR @MucNganSach <= 0 OR @LoaiNganSach IS NULL OR @LoaiNganSach NOT IN (N'Ngày', N'Tuần', N'Tháng')
		   OR @NgayBatDau IS NULL OR @NgayKetThuc IS NULL OR @NgayKetThuc < @NgayBatDau
		   THROW 50020, N'Thông tin ngân sách không hợp lệ.', 1;

			IF EXISTS (SELECT 1 FROM dbo.NganSachAnUong WITH (UPDLOCK, HOLDLOCK) WHERE MaNganSach = @MaNganSach)
			BEGIN
				IF NOT EXISTS (SELECT 1 FROM dbo.NganSachAnUong WHERE MaNganSach = @MaNganSach AND MaNguoiDung = @MaNguoiDung)
					THROW 50021, N'Ngân sách không thuộc người dùng này.', 1;
				UPDATE dbo.NganSachAnUong SET MucNganSach = @MucNganSach, LoaiNganSach = @LoaiNganSach,
					NgayBatDau = @NgayBatDau, NgayKetThuc = @NgayKetThuc WHERE MaNganSach = @MaNganSach;
			END
			ELSE
				INSERT dbo.NganSachAnUong (MaNganSach, MaNguoiDung, MucNganSach, LoaiNganSach, NgayBatDau, NgayKetThuc)
				VALUES (@MaNganSach, @MaNguoiDung, @MucNganSach, @LoaiNganSach, @NgayBatDau, @NgayKetThuc);

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpThemSoThichKhauVi
		@MaSoThichKhauVi NVARCHAR(20),
		@MaNguoiDung      NVARCHAR(20),
		@MaKhauVi         NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			-- Kiểm tra tham số
			IF @MaSoThichKhauVi IS NULL
			   OR LEN(LTRIM(RTRIM(@MaSoThichKhauVi))) = 0
				THROW 51031, N'@MaSoThichKhauVi không được để trống.', 1;

			IF @MaNguoiDung IS NULL
			   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51031, N'@MaNguoiDung không được để trống.', 1;

			IF @MaKhauVi IS NULL
			   OR LEN(LTRIM(RTRIM(@MaKhauVi))) = 0
				THROW 51031, N'@MaKhauVi không được để trống.', 1;

			-- Người dùng phải tồn tại và đang hoạt động
			EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

			-- Khẩu vị phải tồn tại
			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.KhauVi
				WHERE MaKhauVi = @MaKhauVi
			)
				THROW 50022, N'Khẩu vị không tồn tại.', 1;

			-- Không cho cùng mã bản ghi thuộc đối tượng khác
			IF EXISTS
			(
				SELECT 1
				FROM dbo.SoThichKhauVi WITH (UPDLOCK, HOLDLOCK)
				WHERE MaSoThichKhauVi = @MaSoThichKhauVi
				  AND (
						MaNguoiDung <> @MaNguoiDung
						OR MaKhauVi <> @MaKhauVi
					  )
			)
				THROW 51030, N'Mã sở thích khẩu vị đã thuộc đối tượng khác.', 1;

			-- Không thêm trùng sở thích
			IF EXISTS
			(
				SELECT 1
				FROM dbo.SoThichKhauVi WITH (UPDLOCK, HOLDLOCK)
				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaKhauVi = @MaKhauVi
			)
			BEGIN
				SELECT N'DATONTAI' AS TrangThai;
			END
			ELSE
			BEGIN
				INSERT INTO dbo.SoThichKhauVi
				(
					MaSoThichKhauVi,
					MaNguoiDung,
					MaKhauVi
				)
				VALUES
				(
					@MaSoThichKhauVi,
					@MaNguoiDung,
					@MaKhauVi
				);

				SELECT N'DATHEM' AS TrangThai;
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpCapNhatThucDon
	 @MaNguoiDung NVARCHAR(20),
	 @MaThucDon NVARCHAR(20),
	 @TenThucDon NVARCHAR(150),
	 @LoaiThucDon NVARCHAR(30),
	 @NgayBatDau DATE,
	 @NgayKetThuc DATE,
	 @TrangThai NVARCHAR(30)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;

		IF @MaNguoiDung IS NULL
		   OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaNguoiDung không được để trống.',1;

		IF @MaThucDon IS NULL
		   OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThucDon không được để trống.',1;

		IF @TenThucDon IS NULL
		   OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@TenThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@TenThucDon không được để trống.',1;

		IF @LoaiThucDon IS NULL
		   OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@LoaiThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@LoaiThucDon không được để trống.',1;

		IF @TrangThai IS NULL
		   OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@TrangThai,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@TrangThai không được để trống.',1;

		EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon;

		UPDATE dbo.ThucDon
		SET TenThucDon=@TenThucDon,
			LoaiThucDon=@LoaiThucDon,
			NgayBatDau=@NgayBatDau,
			NgayKetThuc=@NgayKetThuc,
			TrangThai=@TrangThai
		WHERE MaThucDon=@MaThucDon;

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpTuyBienNguyenLieuThucDon
	 @MaNguoiDung NVARCHAR(20),
	 @MaThucDon NVARCHAR(20),
	 @MaChiTiet NVARCHAR(20),
	 @MaThanhPhan NVARCHAR(20),
	 @MaNguyenLieu NVARCHAR(20),
	 @MaDonVi NVARCHAR(20),
	 @SoLuong DECIMAL(12,3)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;

		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaNguoiDung không được để trống.',1;

		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThucDon không được để trống.',1;

		IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaChiTiet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaChiTiet không được để trống.',1;

		IF @MaThanhPhan IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThanhPhan,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThanhPhan không được để trống.',1;

		IF @MaNguyenLieu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguyenLieu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaNguyenLieu không được để trống.',1;

		IF @MaDonVi IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaDonVi,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaDonVi không được để trống.',1;

		EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon;

		IF NOT EXISTS(
			SELECT 1
			FROM dbo.ChiTietThucDon ct WITH(UPDLOCK,HOLDLOCK)
			JOIN dbo.CongThuc c
			  ON c.MaMonAn=ct.MaMonAn
			JOIN dbo.ThanhPhanCongThuc tp
			  ON tp.MaCongThuc=c.MaCongThuc
			WHERE ct.MaChiTiet=@MaChiTiet
			  AND ct.MaThucDon=@MaThucDon
			  AND tp.MaThanhPhan=@MaThanhPhan
		)
			THROW 51010,N'Thành phần không thuộc món trong chi tiết thực đơn này.',1;

		IF @SoLuong IS NULL OR @SoLuong<=0
			THROW 51011,N'Lượng thay thế cho công thức chuẩn phải lớn hơn 0.',1;

		IF EXISTS(
			SELECT 1
			FROM dbo.TuyBienNguyenLieuThucDon WITH(UPDLOCK,HOLDLOCK)
			WHERE MaChiTiet=@MaChiTiet
			  AND MaThanhPhan=@MaThanhPhan
		)
			UPDATE dbo.TuyBienNguyenLieuThucDon
			SET MaNguyenLieu=@MaNguyenLieu,
				MaDonVi=@MaDonVi,
				SoLuong=@SoLuong
			WHERE MaChiTiet=@MaChiTiet
			  AND MaThanhPhan=@MaThanhPhan;
		ELSE
			INSERT dbo.TuyBienNguyenLieuThucDon
			VALUES(@MaChiTiet,@MaThanhPhan,@MaNguyenLieu,@MaDonVi,@SoLuong);

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpHuyTuyBienNguyenLieu
	 @MaNguoiDung NVARCHAR(20),
	 @MaThucDon NVARCHAR(20),
	 @MaChiTiet NVARCHAR(20),
	 @MaThanhPhan NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;

		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaNguoiDung không được để trống.',1;

		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThucDon không được để trống.',1;

		IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaChiTiet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaChiTiet không được để trống.',1;

		IF @MaThanhPhan IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThanhPhan,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThanhPhan không được để trống.',1;

		EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon;

		IF NOT EXISTS(
			SELECT 1
			FROM dbo.ChiTietThucDon
			WHERE MaChiTiet=@MaChiTiet
			  AND MaThucDon=@MaThucDon
		)
			THROW 51010,N'Chi tiết không thuộc thực đơn.',1;

		DELETE dbo.TuyBienNguyenLieuThucDon
		WHERE MaChiTiet=@MaChiTiet
		  AND MaThanhPhan=@MaThanhPhan;

		IF @@ROWCOUNT=0
			THROW 51012,N'Không tìm thấy tùy biến.',1;

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLayLichSuDanhGiaThucDon
	 @MaNguoiDung NVARCHAR(20),
	 @MaThucDon NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaNguoiDung không được để trống.',1;

		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0
			THROW 51031,N'@MaThucDon không được để trống.',1;

		EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon,1;

		SELECT *
		FROM dbo.DanhGiaDinhDuongThucDon
		WHERE MaThucDon=@MaThucDon
		ORDER BY ThoiDiemDanhGia DESC,MaDanhGia DESC;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLapDanhSachMuaSam
	 @MaNguoiDung NVARCHAR(20),@MaThucDon NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaThucDon không được để trống.',1;
	 EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon,1;
	 SELECT * INTO #ThanhPhan FROM dbo.FnTinhChiTietThucDon(@MaThucDon,NULL);
	 IF NOT EXISTS(SELECT 1 FROM #ThanhPhan) THROW 50028,N'Thực đơn chưa có món.',1;
	 IF EXISTS(SELECT 1 FROM #ThanhPhan WHERE MaNguyenLieu IS NULL OR SoLuongCan IS NULL)
	 THROW 51034,N'Thực đơn có món thiếu công thức hoặc thành phần; chưa lập được danh sách đầy đủ.',1;

	 SELECT MaNguyenLieu,MaDonVi,SUM(SoLuongCan) SoLuongCan
	 INTO #NhuCau FROM #ThanhPhan GROUP BY MaNguyenLieu,MaDonVi;

	 -- Chọn duy nhất một đơn vị đích cho từng nguyên liệu.
	 SELECT MaNguyenLieu,MIN(MaDonVi) MaDonVi
	 INTO #Dich FROM #NhuCau GROUP BY MaNguyenLieu;

	 SELECT d.MaNguyenLieu,n.TenNguyenLieu,d.MaDonVi,
	  CASE WHEN can.ThieuQuyDoi=0 THEN can.SoLuongCan END SoLuongCan,
	  kho.SoLuongHienCo AS SoLuongKhoDaQuyDoi,
	  CASE WHEN can.ThieuQuyDoi=1 OR kho.ThieuQuyDoi=1 THEN NULL
	   WHEN can.SoLuongCan>COALESCE(kho.SoLuongHienCo,0) THEN can.SoLuongCan-COALESCE(kho.SoLuongHienCo,0) ELSE 0 END SoLuongCanMua,
	  CASE WHEN can.ThieuQuyDoi=1 OR kho.ThieuQuyDoi=1 THEN N'Cần bổ sung quy đổi'
		   ELSE N'Đã tính theo kho hiện tại, chưa trừ kho' END TrangThai,
	  (SELECT nc.MaDonVi,nc.SoLuongCan
	   FROM #NhuCau nc
	   WHERE nc.MaNguyenLieu=d.MaNguyenLieu
	   ORDER BY nc.MaDonVi FOR JSON PATH) NhuCauGocJson
	 FROM #Dich d
	 JOIN dbo.NguyenLieu n ON n.MaNguyenLieu=d.MaNguyenLieu
	 OUTER APPLY(
	  SELECT SUM(q.luong) SoLuongCan,
			 MAX(CASE WHEN q.luong IS NULL THEN 1 ELSE 0 END) ThieuQuyDoi
	  FROM #NhuCau nc
	  CROSS APPLY(
	   SELECT dbo.FnQuyDoiSoLuong(nc.MaNguyenLieu,nc.SoLuongCan,nc.MaDonVi,d.MaDonVi) luong
	  ) q
	  WHERE nc.MaNguyenLieu=d.MaNguyenLieu
	 ) can
	 OUTER APPLY(
	  SELECT SUM(q.luong) SoLuongHienCo,
			 MAX(CASE WHEN q.luong IS NULL THEN 1 ELSE 0 END) ThieuQuyDoi
	  FROM dbo.NguyenLieuHienCo h
	  CROSS APPLY(
	   SELECT dbo.FnQuyDoiSoLuong(h.MaNguyenLieu,h.SoLuong,h.MaDonVi,d.MaDonVi) luong
	  ) q
	  WHERE h.MaNguoiDung=@MaNguoiDung
		AND h.MaNguyenLieu=d.MaNguyenLieu
		AND h.SoLuong>0
	 ) kho;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpTimKiemNguyenLieu
	 @TuKhoa NVARCHAR(150)=NULL
	AS
	BEGIN
		SET NOCOUNT ON;

	 SELECT MaNguyenLieu,TenNguyenLieu,MoTa
	 FROM dbo.NguyenLieu
	 WHERE @TuKhoa IS NULL
		OR TenNguyenLieu LIKE N'%'+@TuKhoa+N'%'
		OR MoTa LIKE N'%'+@TuKhoa+N'%'
	 ORDER BY TenNguyenLieu,MaNguyenLieu;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpTimKiemThucDon
	 @MaNguoiDung NVARCHAR(20),@TuKhoa NVARCHAR(150)=NULL,@TuNgay DATE=NULL,@DenNgay DATE=NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;

	 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

	 IF @TuNgay>@DenNgay THROW 50017,N'Khoảng ngày tra cứu không hợp lệ.',1;

	 SELECT t.*
	 FROM dbo.ThucDon t
	 WHERE MaNguoiDung=@MaNguoiDung
	 AND (@TuNgay IS NULL OR NgayKetThuc>=@TuNgay)
	 AND (@DenNgay IS NULL OR NgayBatDau<=@DenNgay)
	 AND (
		  @TuKhoa IS NULL
		  OR TenThucDon LIKE N'%'+@TuKhoa+N'%'
		  OR EXISTS(
			  SELECT 1
			  FROM dbo.ChiTietThucDon ct
			  JOIN dbo.MonAn m ON m.MaMonAn=ct.MaMonAn
			  WHERE ct.MaThucDon=t.MaThucDon
			  AND m.TenMonAn LIKE N'%'+@TuKhoa+N'%'
		  )
	 )
	 ORDER BY NgayBatDau DESC,MaThucDon;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpGuiPhanHoiCheBien
	 @MaPhanHoi NVARCHAR(20),@MaNguoiDung NVARCHAR(20),@MaCongThuc NVARCHAR(20),
	 @ThoiDiemNau DATETIME2(0),@ThanhCong BIT,@NoiDung NVARCHAR(1500)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;

		IF @MaPhanHoi IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaPhanHoi,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaPhanHoi không được để trống.',1;
		IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
		IF @MaCongThuc IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaCongThuc,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaCongThuc không được để trống.',1;
		IF @NoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@NoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@NoiDung không được để trống.',1;

	 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

	 -- Timestamp truyền vào theo UTC. Không tự nhận đã nấu từ việc lên kế hoạch.
	 IF @ThoiDiemNau IS NULL OR @ThoiDiemNau>CONVERT(DATETIME2(0),SYSUTCDATETIME())
		THROW 51028,N'Thời điểm nấu phải là thời điểm đã xảy ra (UTC).',1;

	 IF NOT EXISTS(
		 SELECT 1 FROM dbo.CongThuc
		 WHERE MaCongThuc=@MaCongThuc AND DaCongBo=1
	 )
		THROW 51005,N'Công thức chưa công bố.',1;

	 INSERT dbo.PhanHoiCheBien(
		 MaPhanHoi,MaNguoiDung,MaCongThuc,ThoiDiemNau,ThanhCong,NoiDung
	 )
	 VALUES(
		 @MaPhanHoi,@MaNguoiDung,@MaCongThuc,@ThoiDiemNau,@ThanhCong,@NoiDung
	 );

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiCongThuc
	 @MaQuanTri NVARCHAR(20),@MaCongThuc NVARCHAR(20),@CongBo BIT
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
		IF @MaCongThuc IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaCongThuc,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaCongThuc không được để trống.',1;

	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

	 IF @CongBo IS NULL
		THROW 51022,N'Trạng thái công bố không được NULL.',1;

	 UPDATE dbo.CongThuc
	 SET DaCongBo=@CongBo
	 WHERE MaCongThuc=@MaCongThuc;

	 IF @@ROWCOUNT=0
		THROW 51023,N'Công thức không tồn tại.',1;

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLuuThanhPhanCongThuc
	 @MaQuanTri NVARCHAR(20),@MaThanhPhan NVARCHAR(20),@MaCongThuc NVARCHAR(20),
	 @MaNguyenLieu NVARCHAR(20),@MaDonVi NVARCHAR(20),@SoLuong DECIMAL(12,3)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
		IF @MaThanhPhan IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThanhPhan,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaThanhPhan không được để trống.',1;
		IF @MaCongThuc IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaCongThuc,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaCongThuc không được để trống.',1;
		IF @MaNguyenLieu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguyenLieu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguyenLieu không được để trống.',1;
		IF @MaDonVi IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaDonVi,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaDonVi không được để trống.',1;

	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

	 IF EXISTS(
		SELECT 1
		FROM dbo.ThanhPhanCongThuc WITH(UPDLOCK,HOLDLOCK)
		WHERE MaThanhPhan=@MaThanhPhan
		  AND MaCongThuc<>@MaCongThuc
	 )
		THROW 51024,N'Thành phần đã thuộc công thức khác.',1;

	 IF EXISTS(
		SELECT 1
		FROM dbo.ThanhPhanCongThuc
		WHERE MaThanhPhan=@MaThanhPhan
	 )
		UPDATE dbo.ThanhPhanCongThuc
		SET MaNguyenLieu=@MaNguyenLieu,
			MaDonVi=@MaDonVi,
			SoLuong=@SoLuong
		WHERE MaThanhPhan=@MaThanhPhan;
	 ELSE
		INSERT dbo.ThanhPhanCongThuc(
			MaThanhPhan,MaCongThuc,MaNguyenLieu,MaDonVi,SoLuong
		)
		VALUES(
			@MaThanhPhan,@MaCongThuc,@MaNguyenLieu,@MaDonVi,@SoLuong
		);

			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
