	 @NangLuong DECIMAL(10,2),@ChatDam DECIMAL(10,2),@ChatBotDuong DECIMAL(10,2),@ChatBeo DECIMAL(10,2),@ChatXo DECIMAL(10,2),@Natri DECIMAL(10,2)
