	 ELSE INSERT dbo.ThongTinDinhDuong(MaThongTin,MaNguyenLieu,KhoiLuongChuan,MaDonVi,NangLuong,ChatDam,ChatBotDuong,ChatBeo,ChatXo,natri)
	 VALUES(@MaThongTin,@MaNguyenLieu,@KhoiLuongChuan,@MaDonVi,@NangLuong,@ChatDam,@ChatBotDuong,@ChatBeo,@ChatXo,@Natri);
			IF @TranBanDau=0 COMMIT TRANSACTION;
