	CREATE OR ALTER PROCEDURE dbo.SpThongKeSuDung
	 @MaQuanTri NVARCHAR(20),@TuNgay DATE,@DenNgay DATE
	AS
	BEGIN
		SET NOCOUNT ON;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;
	 IF @TuNgay IS NULL OR @DenNgay IS NULL OR @TuNgay>@DenNgay THROW 50017,N'Khoảng thống kê không hợp lệ.',1;
	 -- Lượt được LẬP KẾ HOẠCH, không phải số lần thực tế đã nấu/ăn.
	 SELECT m.MaMonAn,m.TenMonAn,COUNT_BIG(*) SoLuotChon,SUM(CAST(ct.SoKhauPhan AS BIGINT)) TongKhauPhan
	 FROM dbo.ChiTietThucDon ct JOIN dbo.MonAn m ON m.MaMonAn=ct.MaMonAn
	 WHERE ct.NgayDung BETWEEN @TuNgay AND @DenNgay GROUP BY m.MaMonAn,m.TenMonAn ORDER BY SoLuotChon DESC,m.MaMonAn;
	 SELECT t.MaNguyenLieu,n.TenNguyenLieu,t.MaDonVi,SUM(t.SoLuongCan) TongLuongTheoDonVi,
	 COUNT(DISTINCT t.MaChiTiet) SoLuotMonDungNguyenLieu
	 FROM dbo.ThucDon td CROSS APPLY dbo.FnTinhChiTietThucDon(td.MaThucDon,NULL) t
	 JOIN dbo.NguyenLieu n ON n.MaNguyenLieu=t.MaNguyenLieu
	 WHERE t.NgayDung BETWEEN @TuNgay AND @DenNgay GROUP BY t.MaNguyenLieu,n.TenNguyenLieu,t.MaDonVi
	 ORDER BY SoLuotMonDungNguyenLieu DESC,t.MaNguyenLieu,t.MaDonVi;
	 -- Đây là phân bố khẩu vị của món được chọn theo thời gian, không suy ra lịch sử đổi sở thích.
	 SELECT DATEFROMPARTS(YEAR(ct.NgayDung),MONTH(ct.NgayDung),1) thang,k.MaKhauVi,k.TenKhauVi,COUNT_BIG(*) SoLuotChon
	 FROM dbo.ChiTietThucDon ct JOIN dbo.KhauViMonAn km ON km.MaMonAn=ct.MaMonAn JOIN dbo.KhauVi k ON k.MaKhauVi=km.MaKhauVi
	 WHERE ct.NgayDung BETWEEN @TuNgay AND @DenNgay GROUP BY DATEFROMPARTS(YEAR(ct.NgayDung),MONTH(ct.NgayDung),1),k.MaKhauVi,k.TenKhauVi
	 ORDER BY thang,k.MaKhauVi;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLuuNguyenLieu
	 @MaQuanTri NVARCHAR(20),@Ma NVARCHAR(20),@Ten NVARCHAR(150),@MoTa NVARCHAR(500)=NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
