			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpDatKhauViMonAn
	 @MaQuanTri NVARCHAR(20),@MaLienKet NVARCHAR(20),@MaMonAn NVARCHAR(20),@MaKhauVi NVARCHAR(20),@Gan BIT=1
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
		IF @MaLienKet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaLienKet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaLienKet không được để trống.',1;
		IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMonAn,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMonAn không được để trống.',1;
		IF @MaKhauVi IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaKhauVi,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaKhauVi không được để trống.',1;
	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;
	 IF @Gan IS NULL THROW 51033,N'Trạng thái gán không được NULL.',1;
	 IF @Gan=1
	 BEGIN
	  IF EXISTS(SELECT 1 FROM dbo.KhauViMonAn WITH(UPDLOCK,HOLDLOCK) WHERE MaKhauViMonAn=@MaLienKet AND (MaMonAn<>@MaMonAn OR MaKhauVi<>@MaKhauVi)) THROW 51030,N'Mã liên kết thuộc đối tượng khác.',1;
	  IF NOT EXISTS(SELECT 1 FROM dbo.KhauViMonAn WITH(UPDLOCK,HOLDLOCK) WHERE MaMonAn=@MaMonAn AND MaKhauVi=@MaKhauVi)
	   INSERT dbo.KhauViMonAn(MaKhauViMonAn,MaMonAn,MaKhauVi) VALUES(@MaLienKet,@MaMonAn,@MaKhauVi);
	 END
	 ELSE DELETE dbo.KhauViMonAn WHERE MaMonAn=@MaMonAn AND MaKhauVi=@MaKhauVi;
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
