	/* ============================================================
	   BƯỚC 1: CẬP NHẬT RÀNG BUỘC VAI TRÒ
	   Không thay đổi dữ liệu NguoiDung hiện tại
	   ============================================================ */

	DECLARE @TenConstraint SYSNAME;

	/* Tìm CHECK constraint hiện tại có liên quan đến cột VaiTro */
	SELECT TOP 1
		@TenConstraint = cc.name
	FROM sys.check_constraints cc
	JOIN sys.tables t
		ON cc.parent_object_id = t.object_id
	WHERE t.name = N'NguoiDung'
	  AND SCHEMA_NAME(t.schema_id) = N'dbo'
	  AND cc.definition LIKE N'%VaiTro%';

	IF @TenConstraint IS NOT NULL
	BEGIN
		DECLARE @SQL NVARCHAR(MAX);

		SET @SQL =
			N'ALTER TABLE dbo.NguoiDung DROP CONSTRAINT '
			+ QUOTENAME(@TenConstraint) + N';';

		EXEC sp_executesql @SQL;

		PRINT N'Đã xóa CHECK constraint VaiTro cũ: ' + @TenConstraint;
	END;
	ELSE
	BEGIN
		PRINT N'Không tìm thấy CHECK constraint VaiTro cũ.';
	END;
	GO
	/* Tạm thời chấp nhận cả role cũ và role mới.
	   Mục đích: không làm hỏng dữ liệu hiện tại trong quá trình migration. */
	ALTER TABLE dbo.NguoiDung
	ADD CONSTRAINT CK_NguoiDung_VaiTro
	CHECK
	(
		VaiTro IN
		(
			N'Người dùng',
			N'Quản trị viên',       -- role cũ, tạm giữ
			N'Quản trị nội dung',
			N'Quản trị hệ thống'
		)
	);
	GO
	USE QuanLyThucDon;
