	CREATE OR ALTER PROCEDURE dbo.SpDangKyNguoiDung
		@HoTen NVARCHAR(100),
		@ThuDienTu NVARCHAR(150),
		@MatKhauBam NVARCHAR(255)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;
		DECLARE @MaNguoiDung NVARCHAR(20);

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;


			/* =====================================================
			   1. KIỂM TRA DỮ LIỆU
			   ===================================================== */

			IF @HoTen IS NULL
			   OR LEN(LTRIM(RTRIM(
					REPLACE(REPLACE(REPLACE(
						@HoTen,
						NCHAR(9), N' '
					), NCHAR(10), N' '), NCHAR(13), N' ')
			   ))) = 0
			BEGIN
				THROW 51031, N'@HoTen không được để trống.', 1;
			END;


			IF @ThuDienTu IS NULL
			   OR LEN(LTRIM(RTRIM(
					REPLACE(REPLACE(REPLACE(
						@ThuDienTu,
						NCHAR(9), N' '
					), NCHAR(10), N' '), NCHAR(13), N' ')
			   ))) = 0
			BEGIN
				THROW 51031, N'@ThuDienTu không được để trống.', 1;
			END;


			IF @MatKhauBam IS NULL
			   OR LEN(LTRIM(RTRIM(
					REPLACE(REPLACE(REPLACE(
						@MatKhauBam,
						NCHAR(9), N' '
					), NCHAR(10), N' '), NCHAR(13), N' ')
			   ))) = 0
			BEGIN
				THROW 51031, N'@MatKhauBam không được để trống.', 1;
			END;


			/* =====================================================
			   2. CHUẨN HÓA
			   ===================================================== */

			SET @HoTen = LTRIM(RTRIM(@HoTen));

			SET @ThuDienTu =
				LOWER(LTRIM(RTRIM(@ThuDienTu)));


			/* =====================================================
			   3. KHÔNG CHO ĐĂNG KÝ TRÙNG EMAIL
			   ===================================================== */

			IF EXISTS
			(
				SELECT 1
				FROM dbo.NguoiDung WITH (UPDLOCK, HOLDLOCK)
				WHERE LOWER(ThuDienTu) = @ThuDienTu
			)
			BEGIN
				THROW 51032,
					  N'Thư điện tử đã được sử dụng.',
					  1;
			END;


			/* Cấp mã có khóa hàng trong cùng transaction, không dùng MAX + 1. */
			DECLARE @MaCap TABLE (MaMoi NVARCHAR(20), LoaiMa SYSNAME);
			INSERT INTO @MaCap(MaMoi, LoaiMa)
			EXEC dbo.SpCapMaMoi
				@LoaiMa = N'NguoiDung',
				@MaMoi = @MaNguoiDung OUTPUT;


			/* =====================================================
			   5. TẠO TÀI KHOẢN

			   Client KHÔNG được truyền:
			   - VaiTro
			   - TrangThai

			   Tài khoản đăng ký luôn là Người dùng.
			   ===================================================== */

			INSERT INTO dbo.NguoiDung
			(
				MaNguoiDung,
				HoTen,
				ThuDienTu,
				MatKhauBam,
				VaiTro,
				TrangThai
			)
			VALUES
			(
				@MaNguoiDung,
				@HoTen,
				@ThuDienTu,
				@MatKhauBam,
				N'Người dùng',
				N'Đang hoạt động'
			);


			/* =====================================================
			   6. TRẢ MÃ VỀ CHO BACKEND
			   ===================================================== */

			SELECT
				@MaNguoiDung AS MaNguoiDung;


			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY

		BEGIN CATCH

			IF @TranBanDau = 0
			   AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;

			ELSE IF @TranBanDau > 0
				 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	USE QuanLyThucDon;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   SỬA HOÀN TOÀN PHẦN TrangThaiKiemDuyet
	   Không ảnh hưởng 3 cột kiểm duyệt đã tạo
	   ============================================================ */

	DECLARE @SQL NVARCHAR(MAX) = N'';


	/* ------------------------------------------------------------
	   1. Xóa constraint cũ có tên dành cho TrangThaiKiemDuyet
	   nếu nó đang tồn tại
	   ------------------------------------------------------------ */

	IF EXISTS
	(
		SELECT 1
		FROM sys.default_constraints
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhGiaMonAn')
		  AND name = N'DF_DanhGiaMonAn_TrangThaiKiemDuyet'
	)
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		DROP CONSTRAINT DF_DanhGiaMonAn_TrangThaiKiemDuyet;
	END;
	GO
	IF EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhGiaMonAn')
		  AND name = N'CK_DanhGiaMonAn_TrangThaiKiemDuyet'
	)
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		DROP CONSTRAINT CK_DanhGiaMonAn_TrangThaiKiemDuyet;
	END;
	GO
	/* ------------------------------------------------------------
	   2. Nếu cột chưa tồn tại thì tạo cột
	   TẠO LUÔN DEFAULT cùng lúc để tránh lỗi migration trước
	   ------------------------------------------------------------ */

	IF COL_LENGTH(N'dbo.DanhGiaMonAn', N'TrangThaiKiemDuyet') IS NULL
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		ADD TrangThaiKiemDuyet NVARCHAR(20)
			NOT NULL
			CONSTRAINT DF_DanhGiaMonAn_TrangThaiKiemDuyet
			DEFAULT N'Đã duyệt'
			WITH VALUES;
	END;
	GO
	/* ------------------------------------------------------------
	   3. Các đánh giá đang tồn tại được xem là Đã duyệt
	   ------------------------------------------------------------ */

	UPDATE dbo.DanhGiaMonAn
	SET TrangThaiKiemDuyet = N'Đã duyệt'
	WHERE TrangThaiKiemDuyet IS NULL;
	GO
	/* ------------------------------------------------------------
	   4. Đổi DEFAULT:
		  dữ liệu cũ = Đã duyệt
		  đánh giá tạo MỚI = Đã duyệt
	   ------------------------------------------------------------ */

	IF EXISTS
	(
		SELECT 1
		FROM sys.default_constraints
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhGiaMonAn')
		  AND name = N'DF_DanhGiaMonAn_TrangThaiKiemDuyet'
	)
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		DROP CONSTRAINT DF_DanhGiaMonAn_TrangThaiKiemDuyet;
	END;
	GO
	ALTER TABLE dbo.DanhGiaMonAn
	ADD CONSTRAINT DF_DanhGiaMonAn_TrangThaiKiemDuyet
	DEFAULT N'Đã duyệt'
	FOR TrangThaiKiemDuyet;
	GO
	/* ------------------------------------------------------------
	   5. CHECK constraint
	   ------------------------------------------------------------ */

	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhGiaMonAn')
		  AND name = N'CK_DanhGiaMonAn_TrangThaiKiemDuyet'
	)
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		WITH CHECK
		ADD CONSTRAINT CK_DanhGiaMonAn_TrangThaiKiemDuyet
		CHECK
		(
			TrangThaiKiemDuyet IN
			(
				N'Chờ duyệt',
				N'Đã duyệt',
				N'Từ chối'
			)
		);
	END;
	GO
	/* ------------------------------------------------------------
	   6. FK người kiểm duyệt
	   ------------------------------------------------------------ */

	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.foreign_keys
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhGiaMonAn')
		  AND name = N'FK_DanhGiaMonAn_NguoiKiemDuyet'
	)
	BEGIN
		ALTER TABLE dbo.DanhGiaMonAn
		ADD CONSTRAINT FK_DanhGiaMonAn_NguoiKiemDuyet
		FOREIGN KEY (MaNguoiKiemDuyet)
		REFERENCES dbo.NguoiDung(MaNguoiDung);
	END;
	GO
	PRINT N'Hoàn tất cấu trúc kiểm duyệt đánh giá.';
	GO
	USE QuanLyThucDon;
	GO
	USE QuanLyThucDon;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpQuanTriLayDanhGiaMonAn
		@MaQuanTri NVARCHAR(20),
		@TrangThaiKiemDuyet NVARCHAR(20) = NULL,
		@MaMonAn NVARCHAR(20) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;

		/* Chỉ Quản trị nội dung được sử dụng */
		EXEC dbo.SpKiemTraQuanTriNoiDung
			@MaQuanTri = @MaQuanTri;

		/* Kiểm tra trạng thái nếu có truyền vào */
		IF @TrangThaiKiemDuyet IS NOT NULL
		   AND @TrangThaiKiemDuyet NOT IN
		   (
			   N'Chờ duyệt',
			   N'Đã duyệt',
			   N'Từ chối'
		   )
		BEGIN
			THROW 51310,
				  N'Trạng thái kiểm duyệt không hợp lệ.',
				  1;
		END;

		SELECT
			dg.MaDanhGia,
			dg.MaNguoiDung,
			nd.HoTen AS HoTenNguoiDanhGia,

			dg.MaMonAn,
			ma.TenMonAn,

			dg.SoSao,
			dg.NoiDung,
			dg.NgayDanhGia,

			dg.TrangThaiKiemDuyet,

			dg.MaNguoiKiemDuyet,
			qtn.HoTen AS HoTenNguoiKiemDuyet,

			dg.NgayKiemDuyet,
			dg.GhiChuKiemDuyet

		FROM dbo.DanhGiaMonAn AS dg

		INNER JOIN dbo.NguoiDung AS nd
			ON nd.MaNguoiDung = dg.MaNguoiDung

		INNER JOIN dbo.MonAn AS ma
			ON ma.MaMonAn = dg.MaMonAn

		LEFT JOIN dbo.NguoiDung AS qtn
			ON qtn.MaNguoiDung = dg.MaNguoiKiemDuyet

		WHERE
			(
				@TrangThaiKiemDuyet IS NULL
				OR dg.TrangThaiKiemDuyet = @TrangThaiKiemDuyet
			)
			AND
			(
				@MaMonAn IS NULL
				OR dg.MaMonAn = @MaMonAn
			)

		ORDER BY
			CASE
				WHEN dg.TrangThaiKiemDuyet = N'Chờ duyệt' THEN 0
				WHEN dg.TrangThaiKiemDuyet = N'Đã duyệt' THEN 1
				ELSE 2
			END,
			dg.NgayDanhGia DESC,
			dg.MaDanhGia DESC;
	END;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   QUẢN TRỊ NỘI DUNG - DUYỆT / TỪ CHỐI ĐÁNH GIÁ
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpKiemDuyetDanhGiaMonAn
		@MaQuanTri NVARCHAR(20),
		@MaDanhGia NVARCHAR(20),
		@TrangThaiMoi NVARCHAR(20),
		@GhiChu NVARCHAR(500) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION KiemDuyetSave;

			/* Chỉ Quản trị nội dung */
			EXEC dbo.SpKiemTraQuanTriNoiDung
				@MaQuanTri = @MaQuanTri;

			IF @MaDanhGia IS NULL
			   OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
			BEGIN
				THROW 51311,
					  N'@MaDanhGia không được để trống.',
					  1;
			END;

			/* Quản trị chỉ được Duyệt hoặc Từ chối */
			IF @TrangThaiMoi IS NULL
			   OR @TrangThaiMoi NOT IN
			   (
				   N'Đã duyệt',
				   N'Từ chối'
			   )
			BEGIN
				THROW 51312,
					  N'Trạng thái phải là Đã duyệt hoặc Từ chối.',
					  1;
			END;

			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaDanhGia = @MaDanhGia
			)
			BEGIN
				THROW 51313,
					  N'Không tìm thấy đánh giá.',
					  1;
			END;

			UPDATE dbo.DanhGiaMonAn
			SET
				TrangThaiKiemDuyet = @TrangThaiMoi,
				MaNguoiKiemDuyet = @MaQuanTri,
				NgayKiemDuyet = SYSDATETIME(),
				GhiChuKiemDuyet =
					NULLIF(LTRIM(RTRIM(@GhiChu)), N'')
			WHERE MaDanhGia = @MaDanhGia;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0
			   AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;

			ELSE IF @TranBanDau > 0
				 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION KiemDuyetSave;

			THROW;

		END CATCH;
	END;
	GO
	/* ============================================================
	   QUẢN TRỊ NỘI DUNG - XÓA ĐÁNH GIÁ KHÔNG PHÙ HỢP
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpQuanTriXoaDanhGiaMonAn
		@MaQuanTri NVARCHAR(20),
		@MaDanhGia NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION XoaDanhGiaSave;

			/* Chỉ Quản trị nội dung */
			EXEC dbo.SpKiemTraQuanTriNoiDung
				@MaQuanTri = @MaQuanTri;

			IF @MaDanhGia IS NULL
			   OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
			BEGIN
				THROW 51314,
					  N'@MaDanhGia không được để trống.',
					  1;
			END;

			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaDanhGia = @MaDanhGia
			)
			BEGIN
				THROW 51313,
					  N'Không tìm thấy đánh giá.',
					  1;
			END;

			DELETE FROM dbo.DanhGiaMonAn
			WHERE MaDanhGia = @MaDanhGia;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0
			   AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;

			ELSE IF @TranBanDau > 0
				 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION XoaDanhGiaSave;

			THROW;

		END CATCH;
	END;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   1. BỔ SUNG CỘT PHỤC VỤ QUẢN TRỊ NỘI DUNG
	   ============================================================ */

	-- 1.1. Danh mục: trạng thái sử dụng
	IF COL_LENGTH(N'dbo.DanhMucMonAn', N'TrangThaiSuDung') IS NULL
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
		ADD TrangThaiSuDung NVARCHAR(30) NOT NULL
			CONSTRAINT DF_DanhMucMonAn_TrangThaiSuDung
			DEFAULT N'Đang sử dụng' WITH VALUES;
	END;
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'CK_DanhMucMonAn_TrangThaiSuDung'
	)
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
		ADD CONSTRAINT CK_DanhMucMonAn_TrangThaiSuDung
		CHECK (TrangThaiSuDung IN (N'Đang sử dụng', N'Ngừng sử dụng'));
	END;
	GO
	IF COL_LENGTH(N'dbo.MonAn', N'TrangThaiHienThi') IS NULL
	BEGIN
		ALTER TABLE dbo.MonAn
		ADD TrangThaiHienThi NVARCHAR(30) NOT NULL
			CONSTRAINT DF_MonAn_TrangThaiHienThi
			DEFAULT N'Hiển thị' WITH VALUES;
	END;
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'CK_MonAn_TrangThaiHienThi'
	)
	BEGIN
		ALTER TABLE dbo.MonAn
		ADD CONSTRAINT CK_MonAn_TrangThaiHienThi
		CHECK (TrangThaiHienThi IN (N'Hiển thị', N'Ẩn'));
	END;
	GO
	IF COL_LENGTH(N'dbo.DoanPhimHuongDan', N'ThoiLuong') IS NULL
	BEGIN
		ALTER TABLE dbo.DoanPhimHuongDan
		ADD ThoiLuong INT NULL;
	END;
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'CK_DoanPhimHuongDan_ThoiLuong'
	)
	BEGIN
		ALTER TABLE dbo.DoanPhimHuongDan
		ADD CONSTRAINT CK_DoanPhimHuongDan_ThoiLuong
		CHECK (ThoiLuong IS NULL OR ThoiLuong > 0);
	END;
	GO
	IF COL_LENGTH(N'dbo.DoanPhimHuongDan', N'TrangThaiSuDung') IS NULL
	BEGIN
		ALTER TABLE dbo.DoanPhimHuongDan
		ADD TrangThaiSuDung NVARCHAR(30) NOT NULL
			CONSTRAINT DF_DoanPhimHuongDan_TrangThaiSuDung
			DEFAULT N'Đang sử dụng' WITH VALUES;
	END;
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'CK_DoanPhimHuongDan_TrangThaiSuDung'
	)
	BEGIN
		ALTER TABLE dbo.DoanPhimHuongDan
		ADD CONSTRAINT CK_DoanPhimHuongDan_TrangThaiSuDung
		CHECK (TrangThaiSuDung IN (N'Đang sử dụng', N'Ngừng sử dụng'));
	END;
	GO
	/* ============================================================
	   2. THÊM NGÀY CẬP NHẬT
	   Dùng cho "Nội dung vừa cập nhật" trên Dashboard
	   ============================================================ */

	IF COL_LENGTH(N'dbo.DanhMucMonAn', N'NgayCapNhat') IS NULL
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
		ADD NgayCapNhat DATETIME2(0) NOT NULL
			CONSTRAINT DF_DanhMucMonAn_NgayCapNhat
			DEFAULT SYSUTCDATETIME() WITH VALUES;
	END;
	GO
	IF COL_LENGTH(N'dbo.MonAn', N'NgayCapNhat') IS NULL
	BEGIN
		ALTER TABLE dbo.MonAn
		ADD NgayCapNhat DATETIME2(0) NOT NULL
			CONSTRAINT DF_MonAn_NgayCapNhat
			DEFAULT SYSUTCDATETIME() WITH VALUES;
	END;
	GO
	IF COL_LENGTH(N'dbo.CongThuc', N'NgayCapNhat') IS NULL
	BEGIN
		ALTER TABLE dbo.CongThuc
		ADD NgayCapNhat DATETIME2(0) NOT NULL
			CONSTRAINT DF_CongThuc_NgayCapNhat
			DEFAULT SYSUTCDATETIME() WITH VALUES;
	END;
	GO
	IF COL_LENGTH(N'dbo.DoanPhimHuongDan', N'NgayCapNhat') IS NULL
	BEGIN
		ALTER TABLE dbo.DoanPhimHuongDan
		ADD NgayCapNhat DATETIME2(0) NOT NULL
			CONSTRAINT DF_DoanPhimHuongDan_NgayCapNhat
			DEFAULT SYSUTCDATETIME() WITH VALUES;
	END;
	GO
	/* ============================================================
	   3. TRIGGER TỰ GHI NHẬN NGÀY CẬP NHẬT
	   ============================================================ */

	CREATE OR ALTER TRIGGER dbo.TrgDanhMucMonAnNgayCapNhat
	ON dbo.DanhMucMonAn
	AFTER UPDATE
	AS
	BEGIN
		SET NOCOUNT ON;

		IF UPDATE(NgayCapNhat)
			RETURN;

		UPDATE dm
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.DanhMucMonAn dm
		JOIN inserted i
			ON i.MaDanhMuc = dm.MaDanhMuc;
	END;
	GO
	CREATE OR ALTER TRIGGER dbo.TrgMonAnNgayCapNhat
	ON dbo.MonAn
	AFTER UPDATE
	AS
	BEGIN
		SET NOCOUNT ON;

		IF UPDATE(NgayCapNhat)
			RETURN;

		UPDATE m
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.MonAn m
		JOIN inserted i
			ON i.MaMonAn = m.MaMonAn;
	END;
	GO
	CREATE OR ALTER TRIGGER dbo.TrgCongThucNgayCapNhat
	ON dbo.CongThuc
	AFTER UPDATE
	AS
	BEGIN
		SET NOCOUNT ON;

		IF UPDATE(NgayCapNhat)
			RETURN;

		UPDATE c
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.CongThuc c
		JOIN inserted i
			ON i.MaCongThuc = c.MaCongThuc;
	END;
	GO
	CREATE OR ALTER TRIGGER dbo.TrgVideoNgayCapNhat
	ON dbo.DoanPhimHuongDan
	AFTER UPDATE
	AS
	BEGIN
		SET NOCOUNT ON;

		IF UPDATE(NgayCapNhat)
			RETURN;

		UPDATE p
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.DoanPhimHuongDan p
		JOIN inserted i
			ON i.MaDoanPhim = p.MaDoanPhim;
	END;
	GO
	/* Khi sửa nguyên liệu trong công thức,
	   công thức cũng được xem là vừa cập nhật */
	CREATE OR ALTER TRIGGER dbo.TrgThanhPhanCapNhatCongThuc
	ON dbo.ThanhPhanCongThuc
	AFTER INSERT, UPDATE, DELETE
	AS
	BEGIN
		SET NOCOUNT ON;

		UPDATE c
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.CongThuc c
		WHERE c.MaCongThuc IN
		(
			SELECT MaCongThuc FROM inserted
			UNION
			SELECT MaCongThuc FROM deleted
		);
	END;
	GO
	/* Khi sửa bước chế biến,
	   công thức cũng được xem là vừa cập nhật */
	CREATE OR ALTER TRIGGER dbo.TrgBuocCheBienCapNhatCongThuc
	ON dbo.BuocCheBien
	AFTER INSERT, UPDATE, DELETE
	AS
	BEGIN
		SET NOCOUNT ON;

		UPDATE c
		SET NgayCapNhat = SYSUTCDATETIME()
		FROM dbo.CongThuc c
		WHERE c.MaCongThuc IN
		(
			SELECT MaCongThuc FROM inserted
			UNION
			SELECT MaCongThuc FROM deleted
		);
	END;
	GO
	/* ============================================================
	   4. SỬA PROCEDURE LƯU DANH MỤC
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpLuuDanhMucMonAn
		@MaQuanTri NVARCHAR(20),
		@Ma NVARCHAR(20),
		@Ten NVARCHAR(100),
		@MoTa NVARCHAR(500) = NULL,
		@TrangThaiSuDung NVARCHAR(30) = N'Đang sử dụng'
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
				THROW 51031, N'@MaQuanTri không được để trống.', 1;

			IF @Ma IS NULL OR LEN(LTRIM(RTRIM(@Ma))) = 0
				THROW 51031, N'@Ma không được để trống.', 1;

			IF @Ten IS NULL OR LEN(LTRIM(RTRIM(@Ten))) = 0
				THROW 51031, N'@Ten không được để trống.', 1;

			IF @TrangThaiSuDung NOT IN
			   (N'Đang sử dụng', N'Ngừng sử dụng')
				THROW 51210, N'Trạng thái danh mục không hợp lệ.', 1;

			EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.DanhMucMonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaDanhMuc = @Ma
			)
			BEGIN
				UPDATE dbo.DanhMucMonAn
				SET TenDanhMuc = @Ten,
					MoTa = @MoTa,
					TrangThaiSuDung = @TrangThaiSuDung,
					NgayCapNhat = SYSUTCDATETIME()
				WHERE MaDanhMuc = @Ma;
			END
			ELSE
			BEGIN
				INSERT dbo.DanhMucMonAn
				(
					MaDanhMuc,
					TenDanhMuc,
					MoTa,
					TrangThaiSuDung
				)
				VALUES
				(
					@Ma,
					@Ten,
					@MoTa,
					@TrangThaiSuDung
				);
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;
		END CATCH;
	END;
	GO
	/* ============================================================
	   5. SỬA PROCEDURE LƯU MÓN ĂN
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpLuuMonAn
		@MaQuanTri NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@MaDanhMuc NVARCHAR(20),
		@TenMonAn NVARCHAR(150),
		@ThoiGianCheBien INT,
		@DoKho NVARCHAR(30),
		@MoTa NVARCHAR(1000) = NULL,
		@DuongDanAnh NVARCHAR(500) = NULL,
		@TrangThaiHienThi NVARCHAR(30) = N'Hiển thị'
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
				THROW 51031, N'@MaQuanTri không được để trống.', 1;

			IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
				THROW 51031, N'@MaMonAn không được để trống.', 1;

			IF @MaDanhMuc IS NULL OR LEN(LTRIM(RTRIM(@MaDanhMuc))) = 0
				THROW 51031, N'@MaDanhMuc không được để trống.', 1;

			IF @TenMonAn IS NULL OR LEN(LTRIM(RTRIM(@TenMonAn))) = 0
				THROW 51031, N'@TenMonAn không được để trống.', 1;

			IF @ThoiGianCheBien IS NULL OR @ThoiGianCheBien <= 0
				THROW 51211, N'Thời gian chế biến phải lớn hơn 0.', 1;

			IF @DoKho NOT IN (N'Dễ', N'Trung bình', N'Khó')
				THROW 51212, N'Độ khó không hợp lệ.', 1;

			IF @TrangThaiHienThi NOT IN (N'Hiển thị', N'Ẩn')
				THROW 51213, N'Trạng thái hiển thị món ăn không hợp lệ.', 1;

			EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.DanhMucMonAn
				WHERE MaDanhMuc = @MaDanhMuc
			)
				THROW 51214, N'Danh mục món ăn không tồn tại.', 1;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.MonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaMonAn = @MaMonAn
			)
			BEGIN
				UPDATE dbo.MonAn
				SET MaDanhMuc = @MaDanhMuc,
					TenMonAn = @TenMonAn,
					ThoiGianCheBien = @ThoiGianCheBien,
					DoKho = @DoKho,
					MoTa = @MoTa,
					DuongDanAnh = @DuongDanAnh,
					TrangThaiHienThi = @TrangThaiHienThi,
					NgayCapNhat = SYSUTCDATETIME()
				WHERE MaMonAn = @MaMonAn;
			END
			ELSE
			BEGIN
				INSERT dbo.MonAn
				(
					MaMonAn,
					MaDanhMuc,
					TenMonAn,
					ThoiGianCheBien,
					DoKho,
					MoTa,
					DuongDanAnh,
					TrangThaiHienThi
				)
				VALUES
				(
					@MaMonAn,
					@MaDanhMuc,
					@TenMonAn,
					@ThoiGianCheBien,
					@DoKho,
					@MoTa,
					@DuongDanAnh,
					@TrangThaiHienThi
				);
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;
		END CATCH;
	END;
	GO
	/* ============================================================
	   7. PROCEDURE ĐỔI TRẠNG THÁI NHANH
	   Dùng cho nút bật/tắt trên giao diện quản trị
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiDanhMuc
		@MaQuanTri NVARCHAR(20),
		@MaDanhMuc NVARCHAR(20),
		@TrangThai NVARCHAR(30)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		IF @TrangThai NOT IN (N'Đang sử dụng', N'Ngừng sử dụng')
			THROW 51210, N'Trạng thái danh mục không hợp lệ.', 1;

		UPDATE dbo.DanhMucMonAn
		SET TrangThaiSuDung = @TrangThai,
			NgayCapNhat = SYSUTCDATETIME()
		WHERE MaDanhMuc = @MaDanhMuc;

		IF @@ROWCOUNT = 0
			THROW 51202, N'Không tìm thấy danh mục.', 1;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiHienThiMonAn
		@MaQuanTri NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@TrangThai NVARCHAR(30)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		IF @TrangThai NOT IN (N'Hiển thị', N'Ẩn')
			THROW 51213, N'Trạng thái hiển thị món ăn không hợp lệ.', 1;

		UPDATE dbo.MonAn
		SET TrangThaiHienThi = @TrangThai,
			NgayCapNhat = SYSUTCDATETIME()
		WHERE MaMonAn = @MaMonAn;

		IF @@ROWCOUNT = 0
			THROW 51202, N'Không tìm thấy món ăn.', 1;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiVideo
		@MaQuanTri NVARCHAR(20),
		@MaDoanPhim NVARCHAR(20),
		@TrangThai NVARCHAR(30)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		IF @TrangThai NOT IN (N'Đang sử dụng', N'Ngừng sử dụng')
			THROW 51216, N'Trạng thái video không hợp lệ.', 1;

		UPDATE dbo.DoanPhimHuongDan
		SET TrangThaiSuDung = @TrangThai,
			NgayCapNhat = SYSUTCDATETIME()
		WHERE MaDoanPhim = @MaDoanPhim;

		IF @@ROWCOUNT = 0
			THROW 51202, N'Không tìm thấy video.', 1;
	END;
	GO
	/* ============================================================
	   8. DANH SÁCH DANH MỤC CHO TRANG QUẢN TRỊ
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpLayDanhMucQuanTri
		@MaQuanTri NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		SELECT
			dm.MaDanhMuc,
			dm.TenDanhMuc,
			dm.MoTa,
			COUNT(m.MaMonAn) AS SoLuongMonAn,
			dm.TrangThaiSuDung,
			dm.NgayCapNhat
		FROM dbo.DanhMucMonAn dm
		LEFT JOIN dbo.MonAn m
			ON m.MaDanhMuc = dm.MaDanhMuc
		GROUP BY
			dm.MaDanhMuc,
			dm.TenDanhMuc,
			dm.MoTa,
			dm.TrangThaiSuDung,
			dm.NgayCapNhat
		ORDER BY dm.TenDanhMuc;
	END;
	GO
	/* ============================================================
	   9. DANH SÁCH MÓN ĂN CHO TRANG QUẢN TRỊ
	   Hiển thị đúng các cột mô tả trong Word
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpLayMonAnQuanTri
		@MaQuanTri NVARCHAR(20),
		@TuKhoa NVARCHAR(150) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		SELECT
			m.MaMonAn,
			m.TenMonAn,
			m.MaDanhMuc,
			dm.TenDanhMuc,
			m.ThoiGianCheBien,
			m.DoKho,

			CASE
				WHEN c.MaCongThuc IS NULL
					THEN N'Chưa có công thức'
				WHEN c.DaCongBo = 1
					THEN N'Đã công bố'
				ELSE N'Bản nháp'
			END AS TinhTrangCongThuc,

			COUNT(p.MaDoanPhim) AS SoVideoHuongDan,

			m.TrangThaiHienThi,
			m.NgayCapNhat

		FROM dbo.MonAn m

		JOIN dbo.DanhMucMonAn dm
			ON dm.MaDanhMuc = m.MaDanhMuc

		LEFT JOIN dbo.CongThuc c
			ON c.MaMonAn = m.MaMonAn

		LEFT JOIN dbo.DoanPhimHuongDan p
			ON p.MaCongThuc = c.MaCongThuc

		WHERE
			@TuKhoa IS NULL
			OR m.TenMonAn LIKE N'%' + @TuKhoa + N'%'
			OR dm.TenDanhMuc LIKE N'%' + @TuKhoa + N'%'

		GROUP BY
			m.MaMonAn,
			m.TenMonAn,
			m.MaDanhMuc,
			dm.TenDanhMuc,
			m.ThoiGianCheBien,
			m.DoKho,
			c.MaCongThuc,
			c.DaCongBo,
			m.TrangThaiHienThi,
			m.NgayCapNhat

		ORDER BY m.TenMonAn;
	END;
	GO
	/* ============================================================
	   10. DANH SÁCH VIDEO CHO QUẢN TRỊ
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpLayVideoQuanTri
		@MaQuanTri NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		SELECT
			p.MaDoanPhim,
			m.MaMonAn,
			m.TenMonAn,
			c.MaCongThuc,
			p.TieuDe,
			p.DuongDan,
			p.MoTa,
			p.ThoiLuong,
			p.TrangThaiSuDung,
			p.NgayCapNhat
		FROM dbo.DoanPhimHuongDan p

		JOIN dbo.CongThuc c
			ON c.MaCongThuc = p.MaCongThuc

		JOIN dbo.MonAn m
			ON m.MaMonAn = c.MaMonAn

		ORDER BY p.NgayCapNhat DESC,
				 p.MaDoanPhim;
	END;
	GO
	/* ============================================================
	   11. DASHBOARD QUẢN TRỊ NỘI DUNG
	   Result set 1: số liệu tổng quan
	   Result set 2: nội dung vừa cập nhật
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpTrangChuQuanTriNoiDung
		@MaQuanTri NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

		/* -------- Result set 1: Tổng quan -------- */

		SELECT
			(SELECT COUNT(*)
			 FROM dbo.DanhMucMonAn) AS SoDanhMuc,

			(SELECT COUNT(*)
			 FROM dbo.DanhMucMonAn
			 WHERE TrangThaiSuDung = N'Đang sử dụng')
			 AS SoDanhMucDangSuDung,

			(SELECT COUNT(*)
			 FROM dbo.MonAn) AS SoMonAn,

			(SELECT COUNT(*)
			 FROM dbo.MonAn
			 WHERE TrangThaiHienThi = N'Hiển thị')
			 AS SoMonAnDangHienThi,

			(SELECT COUNT(*)
			 FROM dbo.CongThuc) AS SoCongThuc,

			(SELECT COUNT(*)
			 FROM dbo.CongThuc
			 WHERE DaCongBo = 1)
			 AS SoCongThucDaCongBo,

			(SELECT COUNT(*)
			 FROM dbo.DoanPhimHuongDan)
			 AS SoVideo,

			(SELECT COUNT(*)
			 FROM dbo.DoanPhimHuongDan
			 WHERE TrangThaiSuDung = N'Đang sử dụng')
			 AS SoVideoDangSuDung;


		/* -------- Result set 2: Nội dung vừa cập nhật -------- */

		SELECT TOP (10)
			x.LoaiNoiDung,
			x.MaNoiDung,
			x.TenNoiDung,
			x.TrangThai,
			x.NgayCapNhat
		FROM
		(
			SELECT
				N'Danh mục' AS LoaiNoiDung,
				dm.MaDanhMuc AS MaNoiDung,
				dm.TenDanhMuc AS TenNoiDung,
				dm.TrangThaiSuDung AS TrangThai,
				dm.NgayCapNhat
			FROM dbo.DanhMucMonAn dm

			UNION ALL

			SELECT
				N'Món ăn',
				m.MaMonAn,
				m.TenMonAn,
				m.TrangThaiHienThi,
				m.NgayCapNhat
			FROM dbo.MonAn m

			UNION ALL

			SELECT
				N'Công thức',
				c.MaCongThuc,
				m.TenMonAn,
				CASE
					WHEN c.DaCongBo = 1
						THEN N'Đã công bố'
					ELSE N'Bản nháp'
				END,
				c.NgayCapNhat
			FROM dbo.CongThuc c
			JOIN dbo.MonAn m
				ON m.MaMonAn = c.MaMonAn

			UNION ALL

			SELECT
				N'Video',
				p.MaDoanPhim,
				p.TieuDe,
				p.TrangThaiSuDung,
				p.NgayCapNhat
			FROM dbo.DoanPhimHuongDan p
		) x
		ORDER BY
			x.NgayCapNhat DESC,
			x.MaNoiDung;
	END;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   SỬA PHÂN QUYỀN CÁC PROCEDURE QUẢN TRỊ NỘI DUNG
	   CREATE -> ALTER để không bị Msg 2714
	   ============================================================ */

	DECLARE
		@TenProc SYSNAME,
		@SQL NVARCHAR(MAX),
		@ViTriCreate INT;

	DECLARE ProcCursor CURSOR LOCAL FAST_FORWARD FOR
	SELECT name
	FROM sys.procedures
	WHERE name IN
	(
		N'SpLuuDanhMucMonAn',
		N'SpLuuMonAn',
		N'SpLuuVideoHuongDan',

		N'SpDatTrangThaiDanhMuc',
		N'SpDatTrangThaiHienThiMonAn',
		N'SpDatTrangThaiVideo',

		N'SpLayDanhMucQuanTri',
		N'SpLayMonAnQuanTri',
		N'SpLayVideoQuanTri',

		N'SpTrangChuQuanTriNoiDung'
	);

	OPEN ProcCursor;
	FETCH NEXT FROM ProcCursor INTO @TenProc;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @SQL =
			OBJECT_DEFINITION(OBJECT_ID(N'dbo.' + @TenProc));

		IF @SQL IS NOT NULL
		BEGIN
			/* Chuyển quyền cũ -> Quản trị nội dung */
			SET @SQL = REPLACE
			(
				@SQL,
				N'EXEC dbo.SpKiemTraQuanTri @MaQuanTri;',
				N'EXEC dbo.SpKiemTraQuanTriNoiDung @MaQuanTri;'
			);

			SET @SQL = REPLACE
			(
				@SQL,
				N'EXEC dbo.SpKiemTraQuanTri @MaQuanTri',
				N'EXEC dbo.SpKiemTraQuanTriNoiDung @MaQuanTri'
			);

			/* OBJECT_DEFINITION có thể trả về CREATE PROCEDURE.
			   Đổi CREATE đầu tiên thành ALTER. */
			IF UPPER(@SQL) NOT LIKE N'%CREATE OR ALTER PROCEDURE%'
			BEGIN
				SET @ViTriCreate =
					PATINDEX(N'%CREATE%PROCEDURE%', UPPER(@SQL));

				IF @ViTriCreate > 0
				BEGIN
					SET @SQL =
						STUFF(@SQL, @ViTriCreate, 6, N'ALTER');
				END;
			END;

			EXEC sys.sp_executesql @SQL;
		END;

		FETCH NEXT FROM ProcCursor INTO @TenProc;
	END;

	CLOSE ProcCursor;
	DEALLOCATE ProcCursor;
	GO
	USE QuanLyThucDon;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLayChiTietMonAn
		@MaMonAn NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaMonAn IS NULL
		   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
		BEGIN
			THROW 51031,
				  N'@MaMonAn không được để trống.',
				  1;
		END;

		/* Chỉ cho người dùng xem món đang được hiển thị
		   và thuộc danh mục đang sử dụng */
		IF NOT EXISTS
		(
			SELECT 1
			FROM dbo.MonAn m
			JOIN dbo.DanhMucMonAn dm
				ON dm.MaDanhMuc = m.MaDanhMuc
			WHERE m.MaMonAn = @MaMonAn
			  AND m.TrangThaiHienThi = N'Hiển thị'
			  AND dm.TrangThaiSuDung = N'Đang sử dụng'
		)
		BEGIN
			THROW 50006,
				  N'Món ăn không tồn tại hoặc hiện không được hiển thị.',
				  1;
		END;


		/* ========================================================
		   RESULT SET 1
		   Thông tin món + chỉ công thức đã công bố
		   ======================================================== */

		SELECT
			m.MaMonAn,
			m.MaDanhMuc,
			m.TenMonAn,
			m.MoTa,
			m.ThoiGianCheBien,
			m.DoKho,
			m.DuongDanAnh,

			dm.TenDanhMuc,

			c.MaCongThuc,
			c.MoTa AS MoTaCongThuc,
			c.SoKhauPhanChuan

		FROM dbo.MonAn m

		JOIN dbo.DanhMucMonAn dm
			ON dm.MaDanhMuc = m.MaDanhMuc

		LEFT JOIN dbo.CongThuc c
			ON c.MaMonAn = m.MaMonAn
		   AND c.DaCongBo = 1

		WHERE m.MaMonAn = @MaMonAn;


		/* ========================================================
		   RESULT SET 2
		   Nguyên liệu + định lượng
		   Chỉ lấy từ công thức đã công bố
		   ======================================================== */

		SELECT
			tp.MaThanhPhan,
			tp.MaNguyenLieu,
			n.TenNguyenLieu,
			tp.SoLuong,
			tp.MaDonVi,
			d.TenDonVi,
			d.KyHieu

		FROM dbo.CongThuc c

		JOIN dbo.ThanhPhanCongThuc tp
			ON tp.MaCongThuc = c.MaCongThuc

		JOIN dbo.NguyenLieu n
			ON n.MaNguyenLieu = tp.MaNguyenLieu

		JOIN dbo.DonViTinh d
			ON d.MaDonVi = tp.MaDonVi

		WHERE c.MaMonAn = @MaMonAn
		  AND c.DaCongBo = 1

		ORDER BY n.TenNguyenLieu;


		/* ========================================================
		   RESULT SET 3
		   Các bước chế biến
		   ======================================================== */

		SELECT
			b.MaBuoc,
			b.ThuTu,
			b.NoiDung,
			b.ThoiGianThucHien

		FROM dbo.CongThuc c

		JOIN dbo.BuocCheBien b
			ON b.MaCongThuc = c.MaCongThuc

		WHERE c.MaMonAn = @MaMonAn
		  AND c.DaCongBo = 1

		ORDER BY b.ThuTu;


		/* ========================================================
		   RESULT SET 4
		   Video đang sử dụng
		   ======================================================== */

		SELECT
			p.MaDoanPhim,
			p.TieuDe,
			p.DuongDan,
			p.MoTa,
			p.ThoiLuong

		FROM dbo.CongThuc c

		JOIN dbo.DoanPhimHuongDan p
			ON p.MaCongThuc = c.MaCongThuc

		WHERE c.MaMonAn = @MaMonAn
		  AND c.DaCongBo = 1
		  AND p.TrangThaiSuDung = N'Đang sử dụng'

		ORDER BY p.MaDoanPhim;


		/* ========================================================
		   RESULT SET 5
		   Khẩu vị
		   ======================================================== */

		SELECT
			kv.MaKhauVi,
			kv.TenKhauVi

		FROM dbo.KhauViMonAn x

		JOIN dbo.KhauVi kv
			ON kv.MaKhauVi = x.MaKhauVi

		WHERE x.MaMonAn = @MaMonAn

		ORDER BY kv.TenKhauVi;


		/* ========================================================
		   RESULT SET 6
		   Chế độ ăn
		   ======================================================== */

		SELECT
			cd.MaCheDoAn,
			cd.TenCheDoAn

		FROM dbo.CheDoAnMonAn x

		JOIN dbo.CheDoAn cd
			ON cd.MaCheDoAn = x.MaCheDoAn

		WHERE x.MaMonAn = @MaMonAn

		ORDER BY cd.TenCheDoAn;


		/* ========================================================
		   RESULT SET 7
		   Điểm đánh giá
		   CHỈ tính đánh giá đã duyệt
		   ======================================================== */

		SELECT
			CAST
			(
				AVG(CAST(dg.SoSao AS DECIMAL(10,2)))
				AS DECIMAL(4,2)
			) AS DiemTrungBinh,

			COUNT(dg.MaDanhGia) AS SoLuotDanhGia

		FROM dbo.DanhGiaMonAn dg

		WHERE dg.MaMonAn = @MaMonAn
		  AND dg.TrangThaiKiemDuyet = N'Đã duyệt';

	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLayDanhGiaMonAn
		@MaMonAn NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaMonAn IS NULL
		   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
		BEGIN
			THROW 51031,
				  N'@MaMonAn không được để trống.',
				  1;
		END;

		IF NOT EXISTS
		(
			SELECT 1
			FROM dbo.MonAn m
			JOIN dbo.DanhMucMonAn dm
				ON dm.MaDanhMuc = m.MaDanhMuc
			WHERE m.MaMonAn = @MaMonAn
			  AND m.TrangThaiHienThi = N'Hiển thị'
			  AND dm.TrangThaiSuDung = N'Đang sử dụng'
		)
		BEGIN
			THROW 50006,
				  N'Món ăn không tồn tại hoặc hiện không được hiển thị.',
				  1;
		END;

		SELECT
			dg.MaDanhGia,
			dg.MaNguoiDung,
			nd.HoTen AS HoTenNguoiDanhGia,
			dg.SoSao,
			dg.NoiDung,
			dg.NgayDanhGia

		FROM dbo.DanhGiaMonAn dg

		JOIN dbo.NguoiDung nd
			ON nd.MaNguoiDung = dg.MaNguoiDung

		WHERE dg.MaMonAn = @MaMonAn
		  AND dg.TrangThaiKiemDuyet = N'Đã duyệt'

		ORDER BY
			dg.NgayDanhGia DESC,
			dg.MaDanhGia DESC;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpTimKiemMonAn
		@TuKhoa NVARCHAR(150) = NULL,
		@MaDanhMuc NVARCHAR(20) = NULL,
		@DoKho NVARCHAR(30) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;

		SELECT
			m.MaMonAn,
			m.TenMonAn,
			dm.TenDanhMuc,
			m.ThoiGianCheBien,
			m.DoKho,
			m.DuongDanAnh,

			CAST
			(
				AVG(CAST(g.SoSao AS DECIMAL(10,2)))
				AS DECIMAL(4,2)
			) AS DiemDanhGiaTrungBinh,

			COUNT(g.MaDanhGia) AS SoLuotDanhGia

		FROM dbo.MonAn m

		JOIN dbo.DanhMucMonAn dm
			ON dm.MaDanhMuc = m.MaDanhMuc

		LEFT JOIN dbo.DanhGiaMonAn g
			ON g.MaMonAn = m.MaMonAn
		   AND g.TrangThaiKiemDuyet = N'Đã duyệt'

		WHERE
			m.TrangThaiHienThi = N'Hiển thị'
			AND dm.TrangThaiSuDung = N'Đang sử dụng'

			/* Chỉ đưa ra món có công thức đã công bố */
			AND EXISTS
			(
				SELECT 1
				FROM dbo.CongThuc c
				WHERE c.MaMonAn = m.MaMonAn
				  AND c.DaCongBo = 1
			)

			AND
			(
				@TuKhoa IS NULL
				OR m.TenMonAn LIKE N'%' + @TuKhoa + N'%'
				OR m.MoTa LIKE N'%' + @TuKhoa + N'%'
				OR dm.TenDanhMuc LIKE N'%' + @TuKhoa + N'%'
			)

			AND
			(
				@MaDanhMuc IS NULL
				OR m.MaDanhMuc = @MaDanhMuc
			)

			AND
			(
				@DoKho IS NULL
				OR m.DoKho = @DoKho
			)

		GROUP BY
			m.MaMonAn,
			m.TenMonAn,
			dm.TenDanhMuc,
			m.ThoiGianCheBien,
			m.DoKho,
			m.DuongDanAnh

		ORDER BY m.TenMonAn;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpThemMonYeuThich
		@MaMonYeuThich NVARCHAR(20),
		@MaNguoiDung NVARCHAR(20),
		@MaMonAn NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY
			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaMonYeuThich IS NULL
			   OR LEN(LTRIM(RTRIM(@MaMonYeuThich))) = 0
				THROW 51031, N'@MaMonYeuThich không được để trống.', 1;

			IF @MaNguoiDung IS NULL
			   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51031, N'@MaNguoiDung không được để trống.', 1;

			IF @MaMonAn IS NULL
			   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
				THROW 51031, N'@MaMonAn không được để trống.', 1;

			EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

			EXEC dbo.SpKiemTraMonAnCongKhai
				@MaMonAn = @MaMonAn;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.MonYeuThich WITH (UPDLOCK, HOLDLOCK)
				WHERE MaMonYeuThich = @MaMonYeuThich
				  AND
				  (
					  MaNguoiDung <> @MaNguoiDung
					  OR MaMonAn <> @MaMonAn
				  )
			)
				THROW 51030, N'Mã bản ghi đã thuộc đối tượng khác.', 1;

			DELETE dbo.MonKhongThich
			WHERE MaNguoiDung = @MaNguoiDung
			  AND MaMonAn = @MaMonAn;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.MonYeuThich WITH (UPDLOCK, HOLDLOCK)
				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaMonAn = @MaMonAn
			)
			BEGIN
				SELECT N'DATONTAI' AS TrangThai;
			END
			ELSE
			BEGIN
				INSERT dbo.MonYeuThich
				(
					MaMonYeuThich,
					MaNguoiDung,
					MaMonAn,
					NgayThem
				)
				VALUES
				(
					@MaMonYeuThich,
					@MaNguoiDung,
					@MaMonAn,
					CAST(GETDATE() AS DATE)
				);

				SELECT N'DATHEM' AS TrangThai;
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpDatMonKhongThich
		@MaNguoiDung NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@KhongThich BIT = 1
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaNguoiDung IS NULL
			   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51031, N'@MaNguoiDung không được để trống.', 1;

			IF @MaMonAn IS NULL
			   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
				THROW 51031, N'@MaMonAn không được để trống.', 1;

			IF @KhongThich IS NULL
				THROW 51009, N'Trạng thái không thích không được NULL.', 1;

			EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

			IF @KhongThich = 1
			BEGIN
				EXEC dbo.SpKiemTraMonAnCongKhai
					@MaMonAn = @MaMonAn;

				DELETE dbo.MonYeuThich
				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaMonAn = @MaMonAn;

				IF NOT EXISTS
				(
					SELECT 1
					FROM dbo.MonKhongThich WITH (UPDLOCK, HOLDLOCK)
					WHERE MaNguoiDung = @MaNguoiDung
					  AND MaMonAn = @MaMonAn
				)
				BEGIN
					INSERT dbo.MonKhongThich
					(
						MaNguoiDung,
						MaMonAn
					)
					VALUES
					(
						@MaNguoiDung,
						@MaMonAn
					);
				END;
			END
			ELSE
			BEGIN
				DELETE dbo.MonKhongThich
				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaMonAn = @MaMonAn;
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpThemHoacCapNhatDanhGiaMonAn
		@MaDanhGia NVARCHAR(20),
		@MaNguoiDung NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@SoSao INT,
		@NoiDung NVARCHAR(1000) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaDanhGia IS NULL
			   OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
				THROW 51031, N'@MaDanhGia không được để trống.', 1;

			IF @MaNguoiDung IS NULL
			   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51031, N'@MaNguoiDung không được để trống.', 1;

			IF @MaMonAn IS NULL
			   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
				THROW 51031, N'@MaMonAn không được để trống.', 1;

			EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

			EXEC dbo.SpKiemTraMonAnCongKhai
				@MaMonAn = @MaMonAn;

			IF @SoSao IS NULL OR @SoSao NOT BETWEEN 1 AND 5
				THROW 50008, N'Điểm đánh giá phải từ 1 đến 5.', 1;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaDanhGia = @MaDanhGia
				  AND
				  (
					  MaNguoiDung <> @MaNguoiDung
					  OR MaMonAn <> @MaMonAn
				  )
			)
				THROW 51030, N'Mã bản ghi đã thuộc đối tượng khác.', 1;

			IF EXISTS
			(
				SELECT 1
				FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaMonAn = @MaMonAn
			)
			BEGIN

				UPDATE dbo.DanhGiaMonAn
				SET
					SoSao = @SoSao,
					NoiDung = @NoiDung,
					NgayDanhGia = CAST(GETDATE() AS DATE),

					/* Đánh giá được hiển thị ngay sau khi sửa */
					TrangThaiKiemDuyet = N'Đã duyệt',
					MaNguoiKiemDuyet = NULL,
					NgayKiemDuyet = NULL,
					GhiChuKiemDuyet = NULL

				WHERE MaNguoiDung = @MaNguoiDung
				  AND MaMonAn = @MaMonAn;

			END
			ELSE
			BEGIN

				INSERT dbo.DanhGiaMonAn
				(
					MaDanhGia,
					MaNguoiDung,
					MaMonAn,
					SoSao,
					NoiDung,
					NgayDanhGia,

					TrangThaiKiemDuyet,
					MaNguoiKiemDuyet,
					NgayKiemDuyet,
					GhiChuKiemDuyet
				)
				VALUES
				(
					@MaDanhGia,
					@MaNguoiDung,
					@MaMonAn,
					@SoSao,
					@NoiDung,
					CAST(GETDATE() AS DATE),

					N'Đã duyệt',
					NULL,
					NULL,
					NULL
				);

			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpThemHoacCapNhatChiTietThucDon
		@MaChiTiet NVARCHAR(20),
		@MaThucDon NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@NgayDung DATE,
		@BuaAn NVARCHAR(30),
		@SoKhauPhan INT,
		@MaNguoiDung NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;

			IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(@MaChiTiet))) = 0
				THROW 51031, N'@MaChiTiet không được để trống.', 1;

			IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(@MaThucDon))) = 0
				THROW 51031, N'@MaThucDon không được để trống.', 1;

			IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
				THROW 51031, N'@MaMonAn không được để trống.', 1;

			IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51031, N'@MaNguoiDung không được để trống.', 1;

			EXEC dbo.SpKiemTraChuThucDon
				@MaNguoiDung,
				@MaThucDon;

			IF @SoKhauPhan IS NULL OR @SoKhauPhan <= 0
				THROW 50013, N'Khẩu phần phải lớn hơn 0.', 1;

			IF @BuaAn IS NULL
			   OR @BuaAn NOT IN
			   (
				   N'Bữa sáng',
				   N'Bữa trưa',
				   N'Bữa tối',
				   N'Bữa phụ'
			   )
				THROW 50014, N'Bữa ăn không hợp lệ.', 1;

			IF @NgayDung IS NULL
			   OR NOT EXISTS
			   (
				   SELECT 1
				   FROM dbo.ThucDon
				   WHERE MaThucDon = @MaThucDon
					 AND @NgayDung BETWEEN NgayBatDau AND NgayKetThuc
			   )
				THROW 50015, N'Ngày dùng nằm ngoài khoảng thực đơn.', 1;


			/* Nếu là món mới hoặc đổi món -> phải đang công khai.
			   Nếu món đã tồn tại trong chi tiết này thì cho phép giữ
			   để không phá lịch sử/thực đơn đã lập. */
			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.ChiTietThucDon
				WHERE MaChiTiet = @MaChiTiet
				  AND MaThucDon = @MaThucDon
				  AND MaMonAn = @MaMonAn
			)
			BEGIN
				EXEC dbo.SpKiemTraMonAnCongKhai
					@MaMonAn = @MaMonAn;
			END;


			IF EXISTS
			(
				SELECT 1
				FROM dbo.ChiTietThucDon WITH (UPDLOCK, HOLDLOCK)
				WHERE MaChiTiet = @MaChiTiet
				  AND MaThucDon <> @MaThucDon
			)
				THROW 51006,
					  N'Mã chi tiết đã thuộc thực đơn khác; không được chuyển chủ sở hữu.',
					  1;


			/* Đổi sang món khác -> xóa tùy biến nguyên liệu cũ */
			IF EXISTS
			(
				SELECT 1
				FROM dbo.ChiTietThucDon
				WHERE MaChiTiet = @MaChiTiet
				  AND MaMonAn <> @MaMonAn
			)
			BEGIN
				DELETE dbo.TuyBienNguyenLieuThucDon
				WHERE MaChiTiet = @MaChiTiet;
			END;


			IF EXISTS
			(
				SELECT 1
				FROM dbo.ChiTietThucDon
				WHERE MaChiTiet = @MaChiTiet
			)
			BEGIN

				UPDATE dbo.ChiTietThucDon
				SET
					MaMonAn = @MaMonAn,
					NgayDung = @NgayDung,
					BuaAn = @BuaAn,
					SoKhauPhan = @SoKhauPhan
				WHERE MaChiTiet = @MaChiTiet;

			END
			ELSE
			BEGIN

				INSERT dbo.ChiTietThucDon
				(
					MaChiTiet,
					MaThucDon,
					MaMonAn,
					NgayDung,
					BuaAn,
					SoKhauPhan
				)
				VALUES
				(
					@MaChiTiet,
					@MaThucDon,
					@MaMonAn,
					@NgayDung,
					@BuaAn,
					@SoKhauPhan
				);

			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpKiemTraNguyenLieuChoMonAn
		@MaNguoiDung NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@SoKhauPhan INT = 1
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaNguoiDung IS NULL
		   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
			THROW 51031, N'@MaNguoiDung không được để trống.', 1;

		IF @MaMonAn IS NULL
		   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
			THROW 51031, N'@MaMonAn không được để trống.', 1;

		EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

		IF @SoKhauPhan IS NULL OR @SoKhauPhan <= 0
			THROW 51004, N'Khẩu phần phải lớn hơn 0.', 1;

		EXEC dbo.SpKiemTraMonAnCongKhai
			@MaMonAn = @MaMonAn;

		SELECT
			k.*,
			n.TenNguyenLieu,
			d.KyHieu,

			(
				SELECT
					tt.MaNguyenLieuThayThe,
					nt.TenNguyenLieu,
					tt.TyLeQuyDoi

				FROM dbo.NguyenLieuThayThe tt

				JOIN dbo.NguyenLieu nt
					ON nt.MaNguyenLieu = tt.MaNguyenLieuThayThe

				WHERE tt.MaNguyenLieuGoc = k.MaNguyenLieu

				FOR JSON PATH
			) AS NguyenLieuThayTheJson

		FROM dbo.FnKiemTraKhoChoMon
		(
			@MaNguoiDung,
			@MaMonAn,
			@SoKhauPhan
		) k

		JOIN dbo.NguyenLieu n
			ON n.MaNguyenLieu = k.MaNguyenLieu

		JOIN dbo.DonViTinh d
			ON d.MaDonVi = k.MaDonVi

		ORDER BY n.TenNguyenLieu;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpTinhDinhDuongVaChiPhiMon
		@MaMonAn NVARCHAR(20),
		@SoKhauPhan INT,
		@NgayDung DATE,
		@KhuVuc NVARCHAR(150) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaMonAn IS NULL
		   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
			THROW 51031, N'@MaMonAn không được để trống.', 1;

		IF @NgayDung IS NULL
		   OR @SoKhauPhan IS NULL
		   OR @SoKhauPhan <= 0
			THROW 51004, N'Ngày dùng/khẩu phần không hợp lệ.', 1;

		EXEC dbo.SpKiemTraMonAnCongKhai
			@MaMonAn = @MaMonAn;

		SELECT *
		INTO #Mon
		FROM dbo.FnTinhMonAn
		(
			@MaMonAn,
			@SoKhauPhan,
			@NgayDung,
			@KhuVuc
		);

		SELECT
			CASE WHEN COUNT(*) = COUNT(NangLuong)
				 THEN SUM(NangLuong) END AS TongNangLuong,

			CASE WHEN COUNT(*) = COUNT(ChatDam)
				 THEN SUM(ChatDam) END AS TongChatDam,

			CASE WHEN COUNT(*) = COUNT(ChatBotDuong)
				 THEN SUM(ChatBotDuong) END AS TongChatBotDuong,

			CASE WHEN COUNT(*) = COUNT(ChatBeo)
				 THEN SUM(ChatBeo) END AS TongChatBeo,

			CASE WHEN COUNT(*) = COUNT(ChatXo)
				 THEN SUM(ChatXo) END AS TongChatXo,

			CASE WHEN COUNT(*) = COUNT(Natri)
				 THEN SUM(Natri) END AS TongNatri,

			CASE WHEN COUNT(*) = COUNT(ChiPhi)
				 THEN SUM(ChiPhi) END AS TongChiPhi

		FROM #Mon;

		SELECT *
		FROM #Mon
		ORDER BY MaThanhPhan;
	END;
	GO
	USE QuanLyThucDon;
	GO
	/* Bỏ thử nghiệm CRUD phụ thuộc video/công thức demo đã gỡ. */
	GO
