	INSERT INTO dbo.DanhMucMonAn (MaDanhMuc, TenDanhMuc, MoTa, LoaiDanhMuc)
	SELECT n.MaDanhMuc, n.TenDanhMuc, n.MoTa, n.LoaiDanhMuc
	FROM @DanhMucMoi n
	WHERE NOT EXISTS
	(
