	(N'MA104',N'DM013',N'Canh chua cá lóc',N'Canh chua cá lóc với me, thơm, cà chua và rau ăn kèm. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-nau-canh-chua-ca-loc-chuan-nhat-ngon-00828',40,N'Dễ',NULL),
	(N'MA105',N'DM013',N'Canh khổ qua nhồi thịt',N'Khổ qua nhồi thịt nấu mềm trong nước dùng xương. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-lam-kho-qua-nhoi-thit-am-nong-ngay-tet-00537',70,N'Dễ',NULL),
	(N'MA106',N'DM013',N'Súp hải sản tuyết yến',N'Súp cồi sò điệp, thịt càng cua, nấm và tuyết yến. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-lam-sup-hai-san-tuyet-yen-bo-duong-don-gian-ngay-tai-nha-16679',40,N'Dễ',NULL),
	(N'MA107',N'DM013',N'Giò heo hầm đậu nành',N'Giò heo hầm đậu nành, cà rốt, nấm đông cô và táo tàu. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-lam-gio-ham-dau-nanh-mem-ngon-tron-dinh-duong-bang-noi-com-dien-05094',70,N'Trung bình',NULL),
	(N'MA108',N'DM013',N'Canh tôm mọc hạt sen',N'Canh tôm bọc giò sống nấu cùng hạt sen, cà rốt và nấm rơm. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-lam-canh-tom-moc-hat-sen-thanh-mat-cho-ngay-tet-04826',60,N'Dễ',NULL),
	(N'MA109',N'DM013',N'Canh sườn hầm hạt sen',N'Sườn heo hầm hạt sen, cà rốt và bông cải xanh. Nguồn công thức: Điện máy XANH, Cách làm canh sườn hầm hạt sen bổ dưỡng đơn giản tại nhà.',60,N'Dễ',NULL),
	(N'MA110',N'DM013',N'Sườn cay khổng lồ kiểu Thái',N'Sườn hầm mềm dùng cùng nước sốt cay chua kiểu Thái. Nguồn: https://www.dienmayxanh.com/vao-bep/cach-lam-suon-cay-khong-lo-thai-lan-don-gian-sieu-ngon-01120',100,N'Trung bình',NULL);

