	INSERT dbo.BuocCheBien (MaBuoc,MaCongThuc,ThuTu,NoiDung,ThoiGianThucHien)
	VALUES
	(N'BCB10101',N'CT101',1,N'Rửa sạch, cắt thịt bò và đậu hũ; sơ chế kim chi, nấm, hành.',5),(N'BCB10102',N'CT101',2,N'Đun nước với cá cơm khô để lấy nước dùng, sau đó vớt cá.',10),(N'BCB10103',N'CT101',3,N'Cho kim chi, tương ớt Hàn Quốc và hành tây vào nấu sôi.',5),(N'BCB10104',N'CT101',4,N'Thêm thịt bò, đậu hũ và nấm; nấu chín, nêm gia vị và rắc hành.',10),
	(N'BCB10201',N'CT102',1,N'Làm sạch gà ác; khử mùi với gừng, hành tím và rượu. Ướp gà với gia vị, dầu hào và nước tương 20 phút.',25),(N'BCB10202',N'CT102',2,N'Luộc trứng cút; gọt và thái lát củ sen, cà rốt; rửa sạch sâm và hạt sen.',10),(N'BCB10203',N'CT102',3,N'Nấu củ sen 10 phút, thêm sâm và hạt sen hầm tiếp 20 phút.',30),(N'BCB10204',N'CT102',4,N'Thêm gà, trứng cút và gạo lứt rang; hầm 10 phút. Nêm lại, thêm cà rốt và hầm thêm 10–15 phút.',25),
	(N'BCB10301',N'CT103',1,N'Rửa sạch gà, sơ chế nấm và rửa nhanh các vị thuốc bắc.',15),(N'BCB10302',N'CT103',2,N'Cho gà, thuốc bắc và nước dừa vào nồi; đun sôi rồi hạ nhỏ lửa.',15),(N'BCB10303',N'CT103',3,N'Hầm đến khi gà mềm khoảng 2 giờ; nêm gia vị vừa ăn.',110),
	(N'BCB10401',N'CT104',1,N'Làm sạch cá, cắt khúc; sơ chế thơm, cà chua, bạc hà, giá và rau thơm.',10),(N'BCB10402',N'CT104',2,N'Đun me với nước, dầm lấy nước chua rồi lọc bỏ hạt.',5),(N'BCB10403',N'CT104',3,N'Nấu nước me với cà chua và thơm; nêm nước mắm, muối và gia vị.',5),(N'BCB10404',N'CT104',4,N'Thả cá vào nấu chín, lần lượt thêm đậu bắp, bạc hà và giá; hoàn tất với rau thơm.',20),
	(N'BCB10501',N'CT105',1,N'Ngâm mềm nấm mèo, băm nhỏ; trộn với thịt xay, trứng và gia vị.',15),(N'BCB10502',N'CT105',2,N'Bổ đôi khổ qua, bỏ ruột, nhồi nhân thịt vào từng trái.',15),(N'BCB10503',N'CT105',3,N'Đun nước dùng sôi, cho khổ qua vào hầm lửa nhỏ đến khi mềm; nêm lại vừa ăn.',40),
	(N'BCB10601',N'CT106',1,N'Ngâm tuyết yến qua đêm; sơ chế nấm, gừng và các nguyên liệu khô.',10),(N'BCB10602',N'CT106',2,N'Đun nước dùng, thêm kỷ tử, hoài sơn, táo tàu, gừng và các loại nấm; hầm nhỏ lửa 20 phút.',20),(N'BCB10603',N'CT106',3,N'Thêm cồi sò điệp, thịt càng cua, tuyết yến và gia vị; đun sôi lại rồi tắt bếp.',10),
	(N'BCB10701',N'CT107',1,N'Ngâm đậu nành, nấu mềm và xay một phần đậu với nước; sơ chế giò heo, cà rốt và nấm.',20),(N'BCB10702',N'CT107',2,N'Phi thơm hành, gừng; cho giò heo vào áp sơ rồi thêm nước và hầm khoảng 30 phút.',30),(N'BCB10703',N'CT107',3,N'Thêm đậu nành, phần nước đậu, cà rốt, nấm và táo tàu; hầm đến mềm, nêm vừa ăn.',20),
	(N'BCB10801',N'CT108',1,N'Bóc vỏ, rút chỉ tôm; băm tôm và trộn với giò sống, tiêu, hành tím.',10),(N'BCB10802',N'CT108',2,N'Vo hỗn hợp tôm giò thành viên; sơ chế hạt sen, cà rốt, nấm và hành tây.',10),(N'BCB10803',N'CT108',3,N'Nấu hạt sen trong nước dùng đến gần mềm, thêm cà rốt và nấm.',15),(N'BCB10804',N'CT108',4,N'Thả viên mọc vào nồi, nấu chín; nêm nước mắm và rắc rau ngò.',15),
	(N'BCB10901',N'CT109',1,N'Chần sườn qua nước sôi, rửa sạch; sơ chế hạt sen, cà rốt và bông cải.',10),(N'BCB10902',N'CT109',2,N'Nấu sườn với nước dùng và gốc ngò khoảng 15 phút.',15),(N'BCB10903',N'CT109',3,N'Thêm hạt sen và gia vị, hầm đến khi sườn và hạt sen mềm.',20),(N'BCB10904',N'CT109',4,N'Thêm cà rốt và bông cải, nấu chín tới; nêm lại và dùng nóng.',10),
	(N'BCB11001',N'CT110',1,N'Rửa sạch sườn. Nấu nước với gốc ngò, tiêu, hành tây, củ cải và muối.',10),(N'BCB11002',N'CT110',2,N'Thêm sườn, đun sôi rồi hạ lửa và hầm đến khi mềm khoảng 1 giờ.',60),(N'BCB11003',N'CT110',3,N'Vớt sườn, pha nước hầm với nước mắm, nước cốt chanh, ớt và ngò gai; rưới lên sườn khi ăn.',10);

