        nl.Ten,
        nl.MoTa,
        ROW_NUMBER() OVER (ORDER BY nl.Ten) + COALESCE((SELECT MAX(TRY_CONVERT(INT, SUBSTRING(MaNguyenLieu, 3, 10))) FROM dbo.NguyenLieu WHERE MaNguyenLieu LIKE N'NL%'), 0) AS N
    FROM @NL AS nl
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguyenLieu n
        WHERE n.TenNguyenLieu = nl.Ten
    )
)
