INSERT dbo.MonAn(MaMonAn,MaDanhMuc,TenMonAn,MoTa,ThoiGianCheBien,DoKho,DuongDanAnh)
SELECT MaMonAn,N'DM014',Ten,MoTa,Cook,DoKho,NULL FROM @M m WHERE NOT EXISTS(SELECT 1 FROM dbo.MonAn x WHERE x.MaMonAn=m.MaMonAn);
/* Neu ten mon da ton tai tu lan chay truoc, dung lai ma hien co de khong vi pham UNIQUE TenMonAn. */
UPDATE m SET MaMonAn=x.MaMonAn
FROM @M m JOIN dbo.MonAn x ON x.TenMonAn=m.Ten
WHERE x.MaMonAn<>m.MaMonAn;
UPDATE x SET x.ThoiGianChuanBi=m.Prep FROM dbo.MonAn x JOIN @M m ON m.MaMonAn=x.MaMonAn;

INSERT dbo.CongThuc(MaCongThuc,MaMonAn,MoTa,SoKhauPhanChuan,DaCongBo)
SELECT N'CT'+RIGHT(MaMonAn,3),MaMonAn,MoTa,Serv,0 FROM @M m WHERE NOT EXISTS(SELECT 1 FROM dbo.CongThuc c WHERE c.MaMonAn=m.MaMonAn);

