INSERT dbo.MonAn(MaMonAn,MaDanhMuc,TenMonAn,MoTa,ThoiGianCheBien,DoKho,DuongDanAnh)
SELECT MaMonAn,N'DM015',Ten,MoTa,Cook,DoKho,NULL FROM @M m
WHERE NOT EXISTS(SELECT 1 FROM dbo.MonAn x WHERE x.MaMonAn=m.MaMonAn);

UPDATE m SET MaMonAn=x.MaMonAn
FROM @M m JOIN dbo.MonAn x ON x.TenMonAn=m.Ten
WHERE x.MaMonAn<>m.MaMonAn;

UPDATE x SET x.ThoiGianChuanBi=m.Prep
FROM dbo.MonAn x JOIN @M m ON m.MaMonAn=x.MaMonAn;

