DECLARE @B TABLE(CT NVARCHAR(20),ThuTu INT,NoiDung NVARCHAR(1500));
INSERT @B VALUES
(N'CT210',1,N'Lê rửa sạch, gọt bỏ vỏ và cắt thành từng miếng nhỏ. Táo đỏ và kỷ tử ngâm với nước trong 30 phút để làm mềm.'),
(N'CT210',2,N'Đun 1 lít nước lọc cùng với lê và táo đỏ ở lửa nhỏ trong 25 phút cho đến khi sôi. Cho kỷ tử và đường phèn vào, đun thêm 7–10 phút cho đường tan hết rồi tắt bếp.'),
(N'CT210',3,N'Múc chè vào chén và thưởng thức. Có thể dùng lạnh.'),
(N'CT211',1,N'Nấu nước đường theo tỉ lệ 1:1 đến khi nước sôi và đường tan hết; có thể cho lá dứa vào tạo mùi thơm. Vớt lá dứa ra, cho gừng bào mỏng vào, nấu đến khi đường chuyển màu vàng nâu thì tắt bếp.'),
(N'CT211',2,N'Ngâm đậu nành với nước trong 8 tiếng, vớt ra và rửa sạch. Cho đậu vào máy xay cùng nước, xay nhuyễn nhiều lần rồi dùng rây và vải sạch lọc lấy sữa.'),
(N'CT211',3,N'Cho sữa đậu nành vào nồi cùng vài lá dứa, vừa nấu vừa khuấy ở lửa vừa đến khi sữa sôi.'),
(N'CT211',4,N'Hòa tan 10g gelatine vào 60ml nước ấm, cho vào sữa đậu lúc còn nóng và khuấy đều. Chờ nguội hẳn rồi cho vào tủ lạnh 4–6 tiếng cho đông.'),
(N'CT211',5,N'Múc tàu hủ ra chén, chan nước đường đã nguội và thưởng thức. Món này dùng lạnh.'),
(N'CT212',1,N'Cho bột sương sáo đen cùng đường vào nồi, thêm 1 lít nước, khuấy đều và nấu lửa vừa đến khi hỗn hợp sôi, đặc lại. Đổ ra hộp cho nguội rồi làm lạnh. Thực hiện tương tự với bột sương sáo trắng.'),
(N'CT212',2,N'Cho nước cốt dừa, sữa tươi không đường và sữa đặc vào nồi, khuấy đều, nấu lửa vừa 5–10 phút đến khi sôi lăn tăn thì tắt bếp.'),
(N'CT212',3,N'Ngâm hạt é với khoảng 300ml nước và 50g đường đến khi hạt é nở mềm.'),
(N'CT212',4,N'Cắt thạch sương sáo, cho vào chén cùng nước cốt dừa và hạt é rồi thưởng thức.'),
(N'CT213',1,N'Hòa tan 10g gelatin trong 20ml nước, quay lò vi sóng ở công suất trung bình 30 giây. Đun sữa tươi, kem tươi và đường, cho gelatin vào, nấu đến khi sữa sôi rồi tắt bếp. Đổ vào khuôn và làm lạnh 2–3 tiếng.'),
(N'CT213',2,N'Rang hạnh nhân lát đến khi vàng mặt thì tắt bếp.'),
(N'CT213',3,N'Nấu nước đường với 200ml nước và 200g đường, khuấy tan rồi để nguội.'),
(N'CT213',4,N'Lấy khúc bạch ra cắt khối vuông, cho vào chén cùng đá viên, nước đường hoặc nước trái cây đóng hộp, trái cây đóng hộp và rắc hạnh nhân lát lên mặt.'),
(N'CT213',5,N'Thưởng thức chè khúc bạch khi còn lạnh.'),
(N'CT214',1,N'Ngâm đậu đỏ qua đêm, nấu với 2 lít nước trong 1 tiếng. Cho đường phèn và lá dứa vào, nấu tiếp 30 phút.'),
(N'CT214',2,N'Cắt hạt lựu cùi dừa, chia làm hai phần; một phần ướp với nước củ dền, phần còn lại ướp với nước lá dứa. Trộn mỗi phần với bột năng để bột áo quanh cùi dừa, luộc đến khi nổi lên rồi cho vào nước đá.'),
(N'CT214',3,N'Trộn 150g bột năng với 60ml nước sôi, nhào mịn, cán mỏng và cắt thành sợi. Luộc sợi bột đến khi nổi lên rồi cho vào nước đá.'),
(N'CT214',4,N'Cho sữa tươi, nước cốt dừa và sữa đặc vào nồi, khuấy đều, đun đến khi vừa sôi nhẹ thì tắt bếp.'),
(N'CT214',5,N'Cho đá nhuyễn vào chén, xếp đậu đỏ, trân châu dừa, trân châu sợi và thêm sữa dừa rồi thưởng thức.');

INSERT dbo.BuocCheBien(MaBuoc,MaCongThuc,ThuTu,NoiDung,ThoiGianThucHien)
SELECT CONCAT(N'BCB',RIGHT(b.CT,3),RIGHT(N'00'+CONVERT(NVARCHAR(2),b.ThuTu),2)),b.CT,b.ThuTu,b.NoiDung,NULL
FROM @B b WHERE NOT EXISTS(SELECT 1 FROM dbo.BuocCheBien x WHERE x.MaCongThuc=b.CT AND x.ThuTu=b.ThuTu);

INSERT dbo.DoanPhimHuongDan(MaDoanPhim,MaCongThuc,TieuDe,DuongDan,MoTa)
SELECT N'DP'+RIGHT(m.MaMonAn,3),N'CT'+RIGHT(m.MaMonAn,3),m.Ten,m.Video,N'Video YouTube theo tài liệu nguồn.'
FROM @M m WHERE m.Video IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.DoanPhimHuongDan d WHERE d.MaCongThuc=N'CT'+RIGHT(m.MaMonAn,3));

UPDATE c SET DaCongBo=1 FROM dbo.CongThuc c WHERE c.MaCongThuc BETWEEN N'CT210' AND N'CT214';
GO

SELECT m.MaMonAn,m.TenMonAn,m.ThoiGianChuanBi,m.ThoiGianCheBien,m.DoKho,c.SoKhauPhanChuan,d.DuongDan
FROM dbo.MonAn m JOIN dbo.CongThuc c ON c.MaMonAn=m.MaMonAn
LEFT JOIN dbo.DoanPhimHuongDan d ON d.MaCongThuc=c.MaCongThuc
WHERE m.MaMonAn BETWEEN N'MA210' AND N'MA214';
GO

