INSERT dbo.MonAn
(
    MaMonAn,
    MaDanhMuc,
    TenMonAn,
    MoTa,
    ThoiGianCheBien,
    DoKho,
    DuongDanAnh
)
SELECT
    m.MaMonAn,
    m.MaDanhMuc,
    m.TenMonAn,
    m.MoTa,
    m.ThoiGianCheBien,
    m.DoKho,
    NULL
FROM @Mon m
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.MonAn x
    WHERE x.MaMonAn=m.MaMonAn
       OR x.TenMonAn=m.TenMonAn
);

UPDATE x
SET x.ThoiGianChuanBi=m.ThoiGianChuanBi
FROM dbo.MonAn x
JOIN @Mon m ON m.MaMonAn=x.MaMonAn;

