;WITH NguyenLieuMoi AS
(
    SELECT
        tp.TenNguyenLieu,
        ROW_NUMBER() OVER
        (
            ORDER BY tp.TenNguyenLieu
        ) + 300 AS STT
    FROM
    (
        SELECT DISTINCT TenNguyenLieu
        FROM @ThanhPhan
    ) tp
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguyenLieu nl
        WHERE nl.TenNguyenLieu=tp.TenNguyenLieu
    )
)
INSERT dbo.NguyenLieu
(
    MaNguyenLieu,
    TenNguyenLieu,
    MoTa
)
SELECT
    N'NL'+RIGHT(N'000'+CONVERT(NVARCHAR(10),STT),3),
    TenNguyenLieu,
    TenNguyenLieu+N'.'
FROM NguyenLieuMoi;

INSERT dbo.CongThuc
(
    MaCongThuc,
    MaMonAn,
    MoTa,
    SoKhauPhanChuan,
    DaCongBo
)
SELECT
    N'CT'+RIGHT(m.MaMonAn,3),
    m.MaMonAn,
    m.MoTa,
    m.SoKhauPhan,
    0
FROM @Mon m
WHERE EXISTS
(
    SELECT 1
    FROM dbo.MonAn x
    WHERE x.MaMonAn=m.MaMonAn
)
AND NOT EXISTS
(
    SELECT 1
    FROM dbo.CongThuc c
    WHERE c.MaMonAn=m.MaMonAn
);

INSERT dbo.ThanhPhanCongThuc
(
    MaThanhPhan,
    MaCongThuc,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    CONCAT
    (
        N'TP',
        RIGHT(tp.MaCongThuc,3),
        RIGHT
        (
            N'00'+CONVERT
            (
                NVARCHAR(2),
                ROW_NUMBER() OVER
                (
                    PARTITION BY tp.MaCongThuc
                    ORDER BY tp.TenNguyenLieu
                )
            ),
            2
        )
    ),
    tp.MaCongThuc,
    nl.MaNguyenLieu,
    tp.MaDonVi,
    tp.SoLuong
FROM @ThanhPhan tp
JOIN dbo.NguyenLieu nl
    ON nl.TenNguyenLieu=tp.TenNguyenLieu
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.ThanhPhanCongThuc x
    WHERE x.MaCongThuc=tp.MaCongThuc
      AND x.MaNguyenLieu=nl.MaNguyenLieu
);

