INSERT INTO dbo.ThanhPhanCongThuc
(
    MaThanhPhan,
    MaCongThuc,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    N'TP20699',
    c.MaCongThuc,
    nl.MaNguyenLieu,
    N'DVT014',
    1
FROM dbo.CongThuc c
JOIN dbo.MonAn m
    ON m.MaMonAn = c.MaMonAn
JOIN dbo.NguyenLieu nl
    ON nl.TenNguyenLieu = N'Hạt nêm/tiêu xay'
WHERE m.TenMonAn = N'Bánh bao nhân thịt trứng'
  AND NOT EXISTS
  (
      SELECT 1
      FROM dbo.ThanhPhanCongThuc tp
      WHERE tp.MaCongThuc = c.MaCongThuc
        AND tp.MaNguyenLieu = nl.MaNguyenLieu
  );
GO

