(N'BCB20604', N'CT206', 4,
N'~ Gói bánh ~

Bạn thoa 1 ít dầu ăn vào tay, sau đó lấy 1 ít nhân cho trứng cút vào giữa bọc kín lại vo tròn nhân thịt.

Tiếp theo, bạn lấy 1 miếng bột đã ủ cho nhân vào giữ rồi từ từ gấp các mí bột lại tạo hình bánh bao.

Cuối cùng bạn dán 1 lá ngò rí lên đầu bánh bao là hoàn thành nha!

Lưu ý: Để dễ tạo hình bánh bao bạn có thể dùng chén (chén ăn cơm) úp xuống vỏ bánh tạo hình tròn trước khi cho nhân vào nhé!',
15);

