        60,
        180,
        N'Dễ',
        NULL
    );

    INSERT dbo.CongThuc
    (
        MaCongThuc,
        MaMonAn,
        MoTa,
        SoKhauPhanChuan,
        DaCongBo
    )
    VALUES
