Thịt gà với là da ngoài giòn, thịt gà được nêm nếm vừa phải. Chấm thịt gà với muối sả, bạn sẽ cảm nhận được vị cay nồng của sả cùng vị chua nhẹ của lá giang làm cho món ăn thêm lạ miệng, hấp dẫn.

