    FROM dbo.NguyenLieu WHERE TenNguyenLieu = N'Thịt xay';

    INSERT dbo.ThanhPhanCongThuc
    SELECT N'TP957', @MaCongThuc, MaNguyenLieu, N'DVT010', 1
    FROM dbo.NguyenLieu WHERE TenNguyenLieu = N'Cà rốt';

