        N'Video hướng dẫn cách làm nấm xào chua ngọt chay.'
    );

    UPDATE dbo.CongThuc
    SET DaCongBo=1
    WHERE MaCongThuc=@MaCongThuc;

    COMMIT TRANSACTION;

    PRINT N'Đã thêm món Nấm xào chua ngọt chay thành công.';
END TRY
