Cuối cùng bạn nêm nếm lại gia vị cho vừa ăn, thêm hành lá vào và tắt bếp. Bày món ăn ra dĩa, rắc thêm tiêu xay cho dậy mùi thơm là có thể thưởng thức ngay.',
