N'Đậu hũ non chiên xù được rất nhiều bạn yêu thích nhờ vẻ ngoài vàng ươm hấp dẫn, giòn rụm và cực kỳ thơm ngon. Món ăn này không chỉ đổi vị cho bữa cơm gia đình mà còn là món ăn vặt lý tưởng.',
15,5,N'Dễ',NULL);

