            N'Ít',
            N'ít',
            NULL
        );
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.DonViTinh
        WHERE MaDonVi = N'DVT015'
    )
    BEGIN
        INSERT dbo.DonViTinh
        (
            MaDonVi,
            TenDonVi,
            KyHieu,
            HeSoGramChuan
        )
        VALUES
        (
            N'DVT015',
            N'Gói',
            N'gói',
            NULL
