USE QuanLyThucDon;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    IF EXISTS (SELECT 1 FROM dbo.MonAn WHERE MaMonAn = N'MA933')
        THROW 51300, N'Mã món MA933 đã tồn tại.', 1;

    IF EXISTS (SELECT 1 FROM dbo.CongThuc WHERE MaCongThuc = N'CT933')
