        N'CT933',
        N'Cơm thăn bò rong biển',
        N'https://www.youtube.com/watch?v=Y5lP-J3QGZc',
        N'Video hướng dẫn làm cơm thăn bò rong biển.'
    );

    UPDATE dbo.CongThuc
    SET DaCongBo = 1
    WHERE MaCongThuc = N'CT933';

    COMMIT TRANSACTION;

    PRINT N'Đã thêm thành công MA933 - Cơm thăn bò rong biển.';
