    (N'DD073',  N'NL073',  1,  0.00, 0.00, 0.00,  0.00, 38758),-- Muối
    (N'DD1015', N'NL1015', 700,20.00,20.00, 60.00, 0.00, 1600),-- Rong biển
    (N'DD1021', N'NL1021', 28, 1.00, 6.00, 0.00,  1.50, NULL), -- Cà tím
