    (N'DD997',  N'NL997',  41, 0.50, 8.50, 0.50, 0.90, 25);   -- Tương ớt

    -- Cập nhật dòng đã có
    UPDATE dd
    SET
        dd.KhoiLuongChuan = 100,
        dd.MaDonVi = N'DVT001',
        dd.NangLuong = x.NangLuong,
        dd.ChatDam = x.ChatDam,
        dd.ChatBotDuong = x.ChatBotDuong,
        dd.ChatBeo = x.ChatBeo,
        dd.ChatXo = x.ChatXo,
        dd.Natri = x.Natri
    FROM dbo.ThongTinDinhDuong AS dd
    INNER JOIN @DD AS x
        ON x.MaNguyenLieu = dd.MaNguyenLieu;

    -- Thêm dòng chưa có
    INSERT INTO dbo.ThongTinDinhDuong
    (
        MaThongTin,
        MaNguyenLieu,
        KhoiLuongChuan,
        MaDonVi,
        NangLuong,
        ChatDam,
        ChatBotDuong,
        ChatBeo,
        ChatXo,
        Natri
    )
    SELECT
        x.MaThongTin,
        x.MaNguyenLieu,
        100,
        N'DVT001',
        x.NangLuong,
        x.ChatDam,
        x.ChatBotDuong,
        x.ChatBeo,
        x.ChatXo,
        x.Natri
    FROM @DD AS x
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.ThongTinDinhDuong AS dd
        WHERE dd.MaNguyenLieu = x.MaNguyenLieu
    );

    COMMIT TRANSACTION;

    PRINT N'Đã cập nhật và thêm dữ liệu dinh dưỡng thành công.';
END TRY
