Bạn cho khối bột vào tô, quét một lớp dầu, bọc màng thực phẩm rồi để bột nghỉ 2 tiếng.

Khi bột ủ xong, bạn chia thành 16 phần, vo bột lại rồi để bột nghỉ khoảng 5 phút.',
