Lấy khuôn nóng ra, rây bột vào khoảng 2/3 khuôn rồi nướng ở 160 độ C trong 50 phút.

Sau khi nướng, chuyển bánh qua rack, úp ngược bánh ra và để nguội.

Mách nhỏ:
