        SoKhauPhanChuan = 5
    WHERE MaCongThuc = N'CT214';

    DELETE FROM dbo.BuocCheBien
    WHERE MaCongThuc = N'CT214';

    DELETE FROM dbo.ThanhPhanCongThuc
    WHERE MaCongThuc = N'CT214';

    INSERT dbo.ThanhPhanCongThuc
    (
        MaThanhPhan,
        MaCongThuc,
