    WHERE MaMonAn = N'MA107';

    UPDATE dbo.CongThuc
    SET
        MoTa = N'Món canh với chân giò hầm bổ dưỡng, mềm ngon luôn là sự lựa chọn hàng đầu của các bà nội trợ.  &#x20;',
