    VALUES
    (
        N'BCB20801',
        N'CT208',
        1,
        N'~ Ngâm gelatin và tách lòng đỏ - Làm pudding sữa ~

Ngâm 10g gelatin vào nước, cho gelatin nở ra. Đập 2 quả trứng, tách riêng, chỉ lấy lòng đỏ, rồi cho 1 muỗng cà phê vani vào.',
        NULL
    ),
    (
        N'BCB20802',
        N'CT208',
        2,
        N'~ Khuấy hỗn hợp sữa - Làm pudding sữa ~

