        ThoiGianChuanBi = 30,
        ThoiGianCheBien = 90,
        DoKho = N'Dễ'
    WHERE MaMonAn = N'MA216';

    UPDATE dbo.CongThuc
    SET
        MoTa = N'Súp hoành thánh chiên nhân rau củ chay với nước dùng thanh ngọt, hoành thánh chiên giòn giòn cực hấp dẫn.',
        SoKhauPhanChuan = 4
    WHERE MaCongThuc = N'CT216';

